    13	import { createRouteContext, mergeContexts } from './context.js';
    14	import { executeMiddlewareChain, combineMiddleware } from './middleware.js';
    15	import { RouterError, NotFoundError } from './errors.js';
    16	
    17	interface CompiledRouteEntry<TContext> {
    18	  route: Route<TContext>;
    19	  compiledPattern: CompiledPattern;
    20	  fullPath: string;
    21	}
    22	
    23	/**
    24	 * Create a framework-agnostic HTTP router
    25	 */
    26	export function createRouter<TContext = any>(
    27	  options: RouterOptions<TContext>
    28	): Router<TContext> {
    29	  const {
    30	    routes,
    31	    middleware: globalMiddleware = [],
    32	    context: contextFactory,
    33	    onError,
    34	    basePath = '/',
    35	  } = options;
    36	
    37	  // Pre-compile all route patterns
    38	  const compiledRoutes: CompiledRouteEntry<TContext>[] = routes.map((route) => {
    39	    const fullPath = joinPaths(basePath, route.path);
    40	    return {
    41	      route,
    42	      compiledPattern: compilePattern(fullPath),
    43	      fullPath,
    44	    };
    45	  });
    46	
    47	  /**
    48	   * Match a route by method and path
    49	   */
    50	  function match(method: string, path: string): MatchedRoute<TContext> | null {
    51	    const normalizedPath = normalizePath(path);
    52	
    53	    for (const entry of compiledRoutes) {
    54	      if (entry.route.method !== method) {
    55	        continue;
    56	      }
    57	
    58	      const pathMatch = matchPath(entry.compiledPattern, normalizedPath);
    59	      if (pathMatch.matched) {
    60	        return {
    61	          route: entry.route,
    62	          params: pathMatch.params,
    63	        };
    64	      }
    65	    }
    66	
    67	    return null;
    68	  }
    69	
    70	  /**
    71	   * Handle an incoming request
    72	   */
    73	  async function handle(request: Request): Promise<Response> {
    74	    try {
    75	      const url = new URL(request.url);
    76	      const path = url.pathname;
    77	      const method = request.method;
    78	
    79	      // Try to match a route
    80	      const matched = match(method, path);
    81	
    82	      if (!matched) {
    83	        throw new NotFoundError(`Route not found: ${method} ${path}`);
    84	      }
    85	
    86	      // Create route context
    87	      const routeContext = createRouteContext(request, matched.params);
    88	
    89	      // Create user context
    90	      let userContext: TContext;
    91	      if (contextFactory !== undefined) {
    92	        if (typeof contextFactory === 'function') {
    93	          userContext = await (contextFactory as (request: Request) => Promise<TContext> | TContext)(request);
    94	        } else {
    95	          userContext = contextFactory;
    96	        }
    97	      } else {
    98	        userContext = {} as TContext;
    99	      }
   100	
   101	      // Merge contexts
   102	      const fullContext = mergeContexts(userContext, routeContext);
   103	
   104	      // Combine global and route-specific middleware
   105	      const allMiddleware = combineMiddleware(
   106	        globalMiddleware,
   107	        matched.route.middleware
   108	      );
   109	
   110	      // Execute middleware chain + handler
   111	      const response = await executeMiddlewareChain(
   112	        allMiddleware,
   113	        request,
   114	        fullContext,
   115	        async () => matched.route.handler(request, fullContext)
   116	      );
   117	
   118	      return response;
   119	    } catch (error) {
   120	      // Handle errors
   121	      if (onError) {
   122	        try {
   123	          return await onError(error as Error, request);
   124	        } catch (handlerError) {
   125	          // If error handler itself fails, return 500
   126	          return Response.json(
   127	            { error: 'Internal Server Error' },
   128	            { status: 500 }
   129	          );
   130	        }
   131	      }
   132	
   133	      // Default error handling
   134	      if (error instanceof RouterError) {
   135	        return error.toResponse();
   136	      }
   137	
   138	      // Unknown error - don't expose details
   139	      console.error('Router error:', error);
   140	      return Response.json(
   141	        { error: 'Internal Server Error' },
   142	        { status: 500 }
   143	      );
   144	    }
   145	  }
   146	
   147	  /**
   148	   * Get all routes
   149	   */
   150	  function getRoutes(): Route<TContext>[] {
   151	    return routes;
   152	  }
   153	
   154	  /**
   155	   * Add a route dynamically
   156	   */
   157	  function addRoute(route: Route<TContext>): void {
   158	    routes.push(route);
   159	    const fullPath = joinPaths(basePath, route.path);
   160	    compiledRoutes.push({
   161	      route,
   162	      compiledPattern: compilePattern(fullPath),
   163	      fullPath,
   164	    });
   165	  }
   166	
   167	  /**
   168	   * Add middleware dynamically
   169	   */
   170	  function use(middleware: Middleware<TContext>): void {
   171	    globalMiddleware.push(middleware);
   172	  }
   173	
   174	  // Create router object
   175	  const router: Router<TContext> = {
   176	    handle,
   177	    getRoutes,
   178	    addRoute,
   179	    use,
   180	    match,
   181	    handler: handle, // Alias for convenience
   182	  };
   183	
   184	  return router;
   185	}

