    18	
    19	  for (const entry of entries) {
    20	    if (entry.isDirectory()) {
    21	      if (IGNORED_DIRS.has(entry.name)) {
    22	        continue;
    23	      }
    24	
    25	      walkFiles(rootDir, targetFileName, results, path.join(currentDir, entry.name));
    26	      continue;
    27	    }
    28	
    29	    if (entry.isFile() && entry.name === targetFileName) {
    30	      results.push(path.relative(rootDir, path.join(currentDir, entry.name)));
    31	    }
    32	  }
    33	
    34	  return results;
    35	}
