   160	export function findNearestManifestDir(filePath, manifestDirs) {
   161	  let current = filePath;
   162	
   163	  while (current && current !== ".") {
   164	    if (manifestDirs.has(current)) {
   165	      return current;
   166	    }
   167	
   168	    const parent = path.dirname(current);
   169	    if (parent === current) {
   170	      break;
   171	    }
   172	
   173	    current = parent;
   174	  }
   175	
   176	  return null;
   177	}
