const wd="/Users/serro/Documents/dev/n/worktrees/superfunctions/production-readiness-audit-2026-08-11";
const cmds=[
"npm pkg get name --workspaces --json 2>&1 | jq -r 'to_entries[] | [.key,.value] | @tsv' | sed -n '1,260p'",
"jq -r '.[] | [.slug,.name,.path] | @tsv' release-packages.json | sed -n '1,220p'",
"/opt/homebrew/bin/node -e 'const fs=require(\"fs\"),p=require(\"path\");const root=process.cwd(),rel=JSON.parse(fs.readFileSync(\"release-packages.json\",\"utf8\"));const rp=new Set(rel.map(x=>x.path));const skip=new Set([\"node_modules\",\".git\",\"dist\",\"build\",\"coverage\",\".next\",\".turbo\"]);let a=[];function w(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.isDirectory()&&skip.has(e.name))continue;const q=p.join(d,e.name);if(e.isDirectory())w(q);else if(e.name===\"package.json\"&&q!==p.join(root,\"package.json\")){const j=JSON.parse(fs.readFileSync(q));const r=p.relative(root,p.dirname(q));if(!j.private&&!rp.has(r))a.push([r,j.name||\"\",j.version||\"\",j.scripts?.build||\"\",j.scripts?.test||\"\"]);}}}w(root);for(const x of a.sort((a,b)=>a[0].localeCompare(b[0])))console.log(x.join(\"\\t\"));console.error(\"COUNT\",a.length);' 2>&1",
"/opt/homebrew/bin/node -e 'const fs=require(\"fs\"),p=require(\"path\");const root=process.cwd(),rel=JSON.parse(fs.readFileSync(\"release-packages.json\",\"utf8\"));const ws=JSON.parse(require(\"child_process\").execFileSync(\"npm\",[\"pkg\",\"get\",\"name\",\"--workspaces\",\"--json\"],{encoding:\"utf8\"}));const dirs=new Set(Object.keys(ws));let miss=[];for(const e of rel)if(!dirs.has(e.path))miss.push([e.path,e.name,e.slug]);for(const x of miss)console.log(x.join(\"\\t\"));console.error(\"COUNT\",miss.length);' 2>&1"
];
const out=await Promise.all(cmds.map(async cmd=>(await tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:30000})).output));
out.forEach(text);

