  8	
  9	const repoRoot = process.cwd();
 10	const args = process.argv.slice(2);
 11	const dryRun = args.includes("--dry-run");
 12	const packageDir = args.find((value) => value !== "--dry-run");
 13	
 14	if (!packageDir) {
 15	  console.error("usage: node scripts/ci-run-python-package.mjs [--dry-run] <package-dir>");
 16	  process.exit(1);
 17	}
 18	
 19	const normalizedTargetDir = packageDir.replace(/\/+$/, "");
 20	const pythonPackages = discoverPythonPackages(repoRoot).map((manifest) => ({
 21	  ...manifest,
 22	  name: manifest.name.toLowerCase(),
 23	}));
 24	const manifestsByDir = new Map(pythonPackages.map((manifest) => [manifest.dir, manifest]));
 25	const manifestsByName = new Map(pythonPackages.map((manifest) => [manifest.name, manifest]));
 26	
 27	if (!manifestsByDir.has(normalizedTargetDir)) {
 28	  console.error(`unknown python package: ${normalizedTargetDir}`);
 29	  process.exit(1);
 30	}
 31	
 32	const targetManifest = manifestsByDir.get(normalizedTargetDir);
 33	const installOrder = topologicalLocalDependencies(targetManifest.name, manifestsByName);
 34	const dependencyInstalls = installOrder.filter((manifest) => manifest.dir !== targetManifest.dir);
 35	
 36	const targetCwd = path.join(repoRoot, targetManifest.dir);
 37	const hasTestsDir = existsSync(path.join(targetCwd, "tests"));
 38	
 39	function run(command, commandArgs, options = {}) {
