 41	  console.log(`$ ${rendered}`);
 42	
 43	  if (dryRun) {
 44	    return;
 45	  }
 46	
 47	  execFileSync(command, commandArgs, {
 48	    cwd: options.cwd || repoRoot,
 49	    stdio: "inherit",
 50	  });
 51	}
 52	
 53	if (dependencyInstalls.length > 0) {
 54	  run(
 55	    "python",
 56	    ["-m", "pip", "install", ...dependencyInstalls.flatMap((manifest) => ["-e", manifest.dir])]
 57	  );
 58	}
 59	
 60	const targetSpecifier = targetManifest.hasDevDependencyGroup
 61	  ? `${targetManifest.dir}[dev]`
 62	  : targetManifest.dir;
 63	
 64	run("python", ["-m", "pip", "install", "-e", targetSpecifier]);
 65	
 66	if (!targetManifest.hasDevDependencyGroup) {
 67	  run("python", [
