 69	    "pip",
 70	    "install",
 71	    "build",
 72	    "pytest",
 73	    "pytest-asyncio",
 74	    "pytest-cov",
 75	    "mypy",
 76	    "ruff",
 77	  ]);
 78	}
 79	
 80	run("python", ["-m", "build", "--wheel", "--sdist", "."], { cwd: targetCwd });
 81	
 82	if (targetManifest.hasRuff) {
