    79	export function createResourceAuthMiddleware<TSession extends AuthSession>(
    80	  provider: AuthProvider<TSession>,
    81	  options?: {
    82	    /** Header name containing the resource ID (default: 'x-resource-id') */
    83	    resourceHeader?: string;
    84	    /** Custom context key where session is stored (default: 'auth') */
    85	    contextKey?: string;
    86	    /** Skip paths that don't require resource authorization */
    87	    skipPaths?: string[];
    88	  }
    89	) {
    90	  const resourceHeader = options?.resourceHeader || 'x-resource-id';
    91	  const contextKey = options?.contextKey || 'auth';
    92	  const skipPaths = options?.skipPaths || [];
    93	
    94	  return async (
    95	    request: Request,
    96	    context: any,
    97	    next: () => Promise<Response>
    98	  ): Promise<Response> => {
    99	    // Check if path should skip resource authorization
   100	    const url = new URL(request.url);
   101	    if (skipPaths.some(path => url.pathname === path)) {
   102	      return next();
   103	    }
   104	
   105	    const session = context[contextKey] as TSession;
   106	
   107	    // If no session exists, skip (auth middleware should have already handled this)
   108	    if (!session) {
   109	      return next();
   110	    }
   111	
   112	    // Get resource ID from header
   113	    const resourceId = request.headers.get(resourceHeader);
   114	
   115	    if (!resourceId) {
   116	      throw new AuthorizationError(`Missing ${resourceHeader} header`);
   117	    }
   118	
   119	    // Check authorization using provider if it supports it
   120	    if (provider.authorize) {
   121	      const authorized = await provider.authorize(session, resourceId);
   122	      if (!authorized) {
   123	        throw new AuthorizationError('Access denied to resource');
   124	      }
   125	    } else {
   126	      // Default: check if resource ID is in session's resourceIds
   127	      const resourceIds = Array.isArray(session.resourceIds) ? session.resourceIds : [];
   128	      if (!resourceIds.includes(resourceId)) {
   129	        throw new AuthorizationError('Access denied to resource');
   130	      }
   131	    }
   132	
   133	    // Store resource ID in context for convenience
   134	    context.resourceId = resourceId;
   135	
   136	    return next();
   137	  };
   138	}
