262	  }
263	
264	  const table = schema[model];
265	  if (!table) {
266	    return record;
267	  }
268	
269	  let changed = false;
270	  const next = { ...(record as Record<string, unknown>) };
271	
272	  for (const [fieldName, field] of Object.entries(table.fields)) {
273	    if (!isDateField(field) || !(fieldName in next)) {
274	      continue;
275	    }
276	
277	    const value = next[fieldName];
278	    const converted = direction === 'storage'
279	      ? convertDateForStorage(value, field, `${model}.${fieldName}`)
280	      : convertDateForRuntime(value, field, `${model}.${fieldName}`);

