 47	 * Build Prisma where clause from generic WhereClause array
 48	 */
 49	function buildPrismaWhere(where: WhereClause[]): any {
 50	  if (!where || where.length === 0) return {};
 51	
 52	  const conditions = where.map((clause) => {
 53	    const { field, operator, value } = clause;
 54	
 55	    switch (operator) {
 56	      case 'eq':
 57	        return { [field]: value };
 58	      case 'ne':
 59	        return { [field]: { not: value } };
 60	      case 'gt':
 61	        return { [field]: { gt: value } };
 62	      case 'gte':
 63	        return { [field]: { gte: value } };
 64	      case 'lt':
 65	        return { [field]: { lt: value } };
 66	      case 'lte':
 67	        return { [field]: { lte: value } };
 68	      case 'in':
 69	        return { [field]: { in: Array.isArray(value) ? value : [value] } };
 70	      case 'not_in':
 71	        return { [field]: { notIn: Array.isArray(value) ? value : [value] } };
 72	      case 'contains':
 73	        return { [field]: { contains: value } };
 74	      case 'starts_with':
 75	        return { [field]: { startsWith: value } };
 76	      case 'ends_with':
 77	        return { [field]: { endsWith: value } };
 78	      default:
 79	        throw new Error(`Unsupported operator: ${operator}`);
 80	    }
 81	  });
 82	
 83	  // Combine with AND/OR based on connector
 84	  if (conditions.length === 1) return conditions[0];
 85	
 86	  // Check if any conditions use OR connector
 87	  const hasOr = where.some((c, i) => i > 0 && c.connector === 'OR');
 88	
 89	  if (hasOr) {
 90	    // Mixed AND/OR: group by connector
 91	    const result: any = { AND: [] };
 92	    let currentGroup: any[] = [conditions[0]];
 93	
 94	    for (let i = 1; i < conditions.length; i++) {
 95	      if (where[i].connector === 'OR') {
 96	        // Flush current AND group before starting OR
 97	        if (currentGroup.length > 0) {
 98	          result.AND.push(currentGroup.length === 1 ? currentGroup[0] : { AND: currentGroup });
 99	        }
100	        // Start new group with the OR condition
101	        currentGroup = [conditions[i]];
102	      } else {
103	        // Continue building AND group
104	        currentGroup.push(conditions[i]);
105	      }
106	    }
107	
108	    if (currentGroup.length > 0) {
109	      result.AND.push(currentGroup.length === 1 ? currentGroup[0] : { AND: currentGroup });
110	    }
