158	export function resolvePluginOrder(
159	  plugins: readonly RuntimePlugin[]
160	): readonly string[] {
161	  const pluginMap = new Map(plugins.map((plugin) => [plugin.id, plugin]));
162	  const visiting = new Set<string>();
163	  const visited = new Set<string>();
164	  const ordered: string[] = [];
165	
166	  const visit = (plugin: RuntimePlugin): void => {
167	    if (visited.has(plugin.id)) {
168	      return;
169	    }
170	    if (visiting.has(plugin.id)) {
171	      throw createExtfnError(
172	        'E_PLUGIN_CONFLICT',
173	        `Plugin dependency cycle detected: ${plugin.id}`
174	      );
175	    }
176	
177	    visiting.add(plugin.id);
178	    for (const dependencyId of plugin.dependsOn ?? []) {
179	      const dependency = pluginMap.get(dependencyId);
180	      if (dependency) {
181	        visit(dependency);
182	      }
183	    }
184	    visiting.delete(plugin.id);
185	    visited.add(plugin.id);
186	    ordered.push(plugin.id);
187	  };
188	
189	  for (const plugin of plugins) {
190	    visit(plugin);
191	  }
192	
193	  return ordered;
194	}
