222	function createRouteTable(
223	  baseHandlers: readonly BackgroundHandlerDefinition[],
224	  plugins: readonly RuntimePlugin[],
225	  pluginOrder: readonly string[]
226	): readonly RegisteredRequestHandler[] {
227	  const orderedPlugins = pluginOrder
228	    .map((id) => plugins.find((plugin) => plugin.id === id))
229	    .filter((value): value is RuntimePlugin => Boolean(value));
230	  const pluginHandlers = orderedPlugins.flatMap((plugin) => {
231	    const registered = plugin.registerBackgroundHandlers?.();
232	    if (!registered) {
233	      return [];
234	    }
235	
236	    if (Array.isArray(registered)) {
237	      return registered;
238	    }
239	
240	    throw createExtfnError(
241	      'E_RUNTIME_PROTOCOL',
242	      'Plugin background handlers must be resolved before router creation.'
243	    );
244	  });
245	  const allHandlers = [...baseHandlers, ...pluginHandlers];
246	  const seen = new Set<string>();
247	
248	  return allHandlers.map((handler) => {
249	    if (
250	      typeof handler.namespace !== 'string' ||
251	      typeof handler.method !== 'string' ||
252	      typeof handler.handle !== 'function'
253	    ) {
254	      throw createExtfnError(
255	        'E_CONFIG_INVALID',
256	        'Invalid background handler registration.'
257	      );
258	    }
259	
260	    const routeKey = `${handler.namespace}/${handler.method}`;
261	    if (seen.has(routeKey)) {
262	      throw createExtfnError(
263	        'E_MANIFEST_COLLISION',
264	        `Duplicate background handler route: ${routeKey}`
265	      );
266	    }
267	    seen.add(routeKey);
268	
269	    return {
270	      namespace: handler.namespace,
271	      method: handler.method,
272	      handle: handler.handle,
273	    };
274	  });
275	}
