277	async function withTimeout<T>(task: Promise<T>, timeoutMs: number): Promise<T> {
278	  let timer: NodeJS.Timeout | undefined;
279	
280	  try {
281	    return await Promise.race([
282	      task,
283	      new Promise<T>((_resolve, reject) => {
284	        timer = setTimeout(() => {
285	          reject(createTimeoutError(timeoutMs));
286	        }, timeoutMs);
287	      }),
288	    ]);
289	  } finally {
290	    if (timer) {
291	      clearTimeout(timer);
292	    }
293	  }
294	}
