301	    'message' in error &&
302	    'status' in error &&
303	    'retryable' in error
304	  ) {
305	    return error as ExtfnError;
306	  }
307	
308	  return createExtfnError(
309	    'E_RUNTIME_PROTOCOL',
310	    error instanceof Error ? error.message : 'Runtime protocol failure.'
311	  );
312	}
