    27	export function buildManifest(
    28	  resolvedConfig: ResolvedExtensionConfig,
    29	  target: BrowserTarget,
    30	  outputs: TargetBuildOutputs
    31	): Record<string, unknown> {
    32	  const baseManifest = {
    33	    manifest_version: 3,
    34	    name: resolvedConfig.config.name,
    35	    version: resolvedConfig.config.version,
    36	    ...(resolvedConfig.config.description
    37	      ? { description: resolvedConfig.config.description }
    38	      : {}),
    39	    background: {
    40	      service_worker: outputs.background,
    41	      type: 'module',
    42	    },
    43	  } satisfies Record<string, unknown>;
    44	
    45	  const surfaceManifest = buildSurfaceManifest(
    46	    resolvedConfig.surfaces.filter((surface) => surface.targets.includes(target)),
    47	    outputs.pages
    48	  );
    49	
    50	  const contentManifest = buildContentScriptsManifest(
    51	    resolvedConfig.contentScripts.filter(
    52	      (contentScript) => !contentScript.targets || contentScript.targets.includes(target)
    53	    ),
    54	    outputs.contentScripts
    55	  );
