    72	export function createTargetBuildOutputs(
    73	  resolvedConfig: ResolvedExtensionConfig
    74	): TargetBuildOutputs {
    75	  const pages = Object.fromEntries(
    76	    resolvedConfig.surfaces.map((surface) => [surface.surface, surface.outputPath])
    77	  ) as Partial<Record<ResolvedPageSurface['surface'], string>>;
    78	
    79	  const contentScripts = Object.fromEntries(
    80	    resolvedConfig.contentScripts.map((contentScript) => [
    81	      contentScript.id,
    82	      {
    83	        js: `content/${contentScript.id}.js`,
    84	        css: contentScript.resolvedCss.map((cssPath) =>
    85	          path.posix.join('content', contentScript.id, path.basename(cssPath))
