   102	  const manifest: Record<string, unknown> = {};
   103	
   104	  for (const surface of surfaces) {
   105	    const outputPath = pages[surface.surface];
   106	    if (!outputPath) {
   107	      continue;
   108	    }
   109	
   110	    if (surface.surface === 'popup') {
   111	      manifest.action = {
   112	        default_popup: outputPath,
   113	        ...(surface.title ? { default_title: surface.title } : {}),
   114	      };
   115	    } else if (surface.surface === 'options') {
