   132	  outputs: TargetBuildOutputs['contentScripts']
   133	): Record<string, unknown> {
   134	  if (contentScripts.length === 0) {
   135	    return {};
   136	  }
   137	
   138	  return {
   139	    content_scripts: contentScripts
   140	      .slice()
