   159	        }
   160	
   161	        if (contentScript.allFrames !== undefined) {
   162	          manifestEntry.all_frames = contentScript.allFrames;
   163	        }
   164	
   165	        if (contentScript.world) {
   166	          manifestEntry.world = contentScript.world;
   167	        }
   168	
   169	        return manifestEntry;
   170	      }),
   171	  };
   172	}
