    15	function deepMerge(
    16	  base: Record<string, unknown>,
    17	  incoming: Record<string, unknown>
    18	): Record<string, unknown> {
    19	  const result: Record<string, unknown> = { ...base };
    20	
    21	  for (const [key, value] of Object.entries(incoming)) {
    22	    const currentValue = result[key];
