  8	export interface AnchorContext {
  9	  document: Document;
 10	  moduleId: string;
 11	  resolverLoader?: (
 12	    exportName: string
 13	  ) => Promise<(document: Document) => Iterable<Element> | Element | null | undefined>;
 14	  logger?: (error: unknown) => void;
 15	}
 16	
 17	export interface ResolvedAnchorMount {
 18	  anchor: Element;
 19	  anchorKey: string;
 20	  mountMode: ContentMountMode;
 21	}
 22	
 23	export async function resolveAnchors(
 24	  contentScript: ContentScriptConfig,
 25	  context: AnchorContext
 26	): Promise<ResolvedAnchorMount[]> {
 27	  const strategies = contentScript.anchors ?? [];
 28	  if (strategies.length === 0) {
 29	    return [];
 30	  }
 31	
 32	  const resolved: ResolvedAnchorMount[] = [];
 33	
 34	  for (const strategy of strategies) {
 35	    if (strategy.kind === 'selector') {
 36	      const anchor = context.document.querySelector(strategy.selector);
 37	      if (!anchor) {
 38	        continue;
 39	      }
 40	
 41	      resolved.push({
 42	        anchor,
 43	        anchorKey: createAnchorKey(contentScript.id, anchor, resolved.length),
 44	        mountMode: strategy.mountMode,
 45	      });
 46	      continue;
 47	    }
 48	
 49	    if (strategy.kind === 'selector-list') {
 50	      const anchors = Array.from(
 51	        context.document.querySelectorAll(strategy.selector)
 52	      );
 53	      anchors.forEach((anchor, index) => {
 54	        resolved.push({
 55	          anchor,
 56	          anchorKey: createAnchorKey(contentScript.id, anchor, index),
 57	          mountMode: strategy.mountMode,
 58	        });
 59	      });
 60	      continue;
 61	    }
 62	
 63	    await resolveResolverAnchors(contentScript, strategy, context, resolved);
 64	  }
 65	
 66	  return resolved;
 67	}
 68	
 69	export function createAnchorKey(
 70	  moduleId: string,
 71	  anchor: Element,
 72	  index: number
 73	): string {
 74	  const preferred =
 75	    anchor.getAttribute('data-extfn-anchor-key') ??
 76	    anchor.getAttribute('data-testid') ??
 77	    anchor.id ??
 78	    anchor.getAttribute('name');
 79	
 80	  if (preferred) {
 81	    return `${moduleId}/${preferred}`;
 82	  }
 83	
 84	  return `${moduleId}/anchor-${index}`;
 85	}
 86	
 87	async function resolveResolverAnchors(
 88	  contentScript: ContentScriptConfig,
 89	  strategy: Extract<AnchorStrategy, { kind: 'resolver' }>,
 90	  context: AnchorContext,
 91	  resolved: ResolvedAnchorMount[]
 92	): Promise<void> {
 93	  if (!context.resolverLoader) {
 94	    throw createExtfnError(
 95	      'E_ANCHOR_RESOLUTION',
 96	      `Resolver loader is unavailable for ${contentScript.id}/${strategy.exportName}`
 97	    );
 98	  }
 99	
100	  try {
101	    const resolver = await context.resolverLoader(strategy.exportName);
102	    const output = resolver(context.document);
103	    const anchors = normalizeResolverResult(output);
104	
105	    anchors.forEach((anchor, index) => {
106	      resolved.push({
107	        anchor,
108	        anchorKey: createAnchorKey(contentScript.id, anchor, index),
109	        mountMode: strategy.mountMode,
110	      });
111	    });
112	  } catch (error) {
113	    context.logger?.(
114	      createExtfnError(
115	        'E_ANCHOR_RESOLUTION',
116	        error instanceof Error ? error.message : 'Anchor resolver failed.',
117	        { id: contentScript.id, exportName: strategy.exportName }
118	      )
119	    );
120	  }
121	}
122	
123	function normalizeResolverResult(
124	  value: Iterable<Element> | Element | null | undefined
125	): Element[] {
126	  if (!value) {
127	    return [];
128	  }
129	
130	  if (isElementNode(value)) {
131	    return [value];
132	  }
133	
134	  return Array.from(value).filter(isElementNode);
135	}
136	
137	function isElementNode(value: unknown): value is Element {
138	  return (
139	    typeof value === 'object' &&
140	    value !== null &&
141	    'nodeType' in value &&
142	    (value as { nodeType: number }).nodeType === 1
143	  );
144	}
