  2	import type { AnchorContext, ResolvedAnchorMount } from './anchors.js';
  3	import { resolveAnchors } from './anchors.js';
  4	import { MountRegistry } from './mountRegistry.js';
  5	
  6	export interface MountContentScriptOptions extends AnchorContext {
  7	  registry: MountRegistry;
  8	  render: (mount: {
  9	    moduleId: string;
 10	    anchorKey: string;
 11	    root: HTMLElement;
 12	    styleTarget: HTMLElement | ShadowRoot;
 13	    shadowRoot?: ShadowRoot;
 14	  }) => void | (() => void);
 15	}
 16	
 17	export async function mountContentScript(
 18	  contentScript: ContentScriptConfig,
 19	  options: MountContentScriptOptions
 20	): Promise<HTMLElement[]> {
 21	  const resolvedAnchors = await resolveAnchors(contentScript, options);
 22	  const mountedRoots: HTMLElement[] = [];
 23	  const seenKeys = new Set<string>();
 24	
 25	  for (const resolvedAnchor of resolvedAnchors) {
 26	    seenKeys.add(resolvedAnchor.anchorKey);
 27	    const mounted = mountSingleAnchor(contentScript, resolvedAnchor, options);
 28	    mountedRoots.push(mounted);
 29	  }
 30	
 31	  for (const existing of options.registry.entriesForModule(contentScript.id)) {
 32	    if (!seenKeys.has(existing.anchorKey) && !existing.anchor.isConnected) {
 33	      options.registry.remove(contentScript.id, existing.anchorKey);
 34	    }
 35	  }
 36	
 37	  return mountedRoots;
 38	}
 39	
 40	function mountSingleAnchor(
 41	  contentScript: ContentScriptConfig,
 42	  resolvedAnchor: ResolvedAnchorMount,
 43	  options: MountContentScriptOptions
 44	): HTMLElement {
 45	  const existing = options.registry.get(contentScript.id, resolvedAnchor.anchorKey);
 46	
 47	  if (existing && existing.anchor === resolvedAnchor.anchor && existing.root.isConnected) {
 48	    ensureStyles(contentScript, existing.root, existing.styleTarget, existing.shadowRoot);
 49	    return existing.root;
 50	  }
 51	
 52	  if (existing) {
 53	    options.registry.remove(contentScript.id, resolvedAnchor.anchorKey);
 54	  }
 55	
 56	  const root = options.document.createElement('div');
 57	  root.dataset.extfnModuleId = contentScript.id;
 58	  root.dataset.extfnAnchorKey = resolvedAnchor.anchorKey;
 59	  root.id = createMountRootId(contentScript.id, resolvedAnchor.anchorKey);
 60	
 61	  let shadowRoot: ShadowRoot | undefined;
 62	  let styleTarget: HTMLElement | ShadowRoot = root;
 63	
 64	  if (contentScript.styleIsolation === 'shadow-root' || resolvedAnchor.mountMode === 'shadow') {
 65	    shadowRoot = root.attachShadow({ mode: 'open' });
 66	    styleTarget = shadowRoot;
 67	  }
 68	
 69	  attachRoot(resolvedAnchor.anchor, root, resolvedAnchor.mountMode);
 70	  ensureStyles(contentScript, root, styleTarget, shadowRoot);
 71	
 72	  const cleanup = options.render({
 73	    moduleId: contentScript.id,
 74	    anchorKey: resolvedAnchor.anchorKey,
 75	    root,
 76	    styleTarget,
 77	    shadowRoot,
 78	  });
 79	
 80	  options.registry.register({
 81	    moduleId: contentScript.id,
 82	    anchorKey: resolvedAnchor.anchorKey,
 83	    anchor: resolvedAnchor.anchor,
 84	    root,
 85	    shadowRoot,
 86	    styleTarget,
 87	    cleanup: typeof cleanup === 'function' ? cleanup : undefined,
 88	  });
 89	
 90	  return root;
 91	}
 92	
 93	export function ensureStyles(
 94	  contentScript: ContentScriptConfig,
 95	  root: HTMLElement,
 96	  styleTarget: HTMLElement | ShadowRoot,
 97	  shadowRoot?: ShadowRoot
 98	): void {
 99	  if (contentScript.normalizeRootStyles) {
100	    root.style.boxSizing = 'border-box';
101	    root.style.fontFamily = 'ui-sans-serif, system-ui, sans-serif';
102	    root.style.fontSize = '14px';
103	    root.style.lineHeight = '1.4';
104	    root.style.color = 'rgb(17, 24, 39)';
105	  }
106	
107	  if (contentScript.css && contentScript.css.length > 0) {
108	    const styleMarker = `${contentScript.id}:styles`;
109	    const styleHost = shadowRoot ?? styleTarget;
110	    const existingStyle = queryStyleHost(styleHost, styleMarker);
111	    if (!existingStyle) {
112	      const styleTag = root.ownerDocument.createElement('style');
113	      styleTag.dataset.extfnStyle = styleMarker;
114	      styleTag.textContent = contentScript.css.join('\n');
115	
116	      if (shadowRoot) {
117	        shadowRoot.appendChild(styleTag);
118	      } else {
119	        styleTarget.appendChild(styleTag);
120	      }
121	    }
122	  }
123	}
124	
125	export function createMountRootId(moduleId: string, anchorKey: string): string {
126	  const suffix = anchorKey.startsWith(`${moduleId}/`)
127	    ? anchorKey.slice(moduleId.length + 1)
128	    : anchorKey;
129	  return `extfn-root-${moduleId}${suffix === 'anchor-0' ? '' : `-${slugify(suffix)}`}`;
130	}
131	
132	function attachRoot(anchor: Element, root: HTMLElement, mountMode: ResolvedAnchorMount['mountMode']): void {
133	  if (mountMode === 'prepend') {
134	    anchor.prepend(root);
135	    return;
136	  }
137	
138	  if (mountMode === 'replace') {
139	    anchor.replaceWith(root);
140	    return;
141	  }
142	
143	  anchor.append(root);
144	}
145	
146	function queryStyleHost(
147	  target: HTMLElement | ShadowRoot,
148	  marker: string
149	): HTMLStyleElement | null {
150	  return target.querySelector(`style[data-extfn-style="${marker}"]`);
151	}
152	
153	function slugify(value: string): string {
154	  return value
155	    .toLowerCase()
156	    .replace(/[^a-z0-9]+/g, '-')
157	    .replace(/^-+|-+$/g, '');
158	}
