  3	export interface MountedContentRoot {
  4	  moduleId: string;
  5	  anchorKey: string;
  6	  anchor: Element;
  7	  root: HTMLElement;
  8	  shadowRoot?: ShadowRoot;
  9	  styleTarget: HTMLElement | ShadowRoot;
