 13	export class MountRegistry {
 14	  private readonly mounts = new Map<string, MountedContentRoot>();
 15	
 16	  get(moduleId: string, anchorKey: string): MountedContentRoot | undefined {
 17	    return this.mounts.get(createRegistryKey(moduleId, anchorKey));
 18	  }
 19	
 20	  register(mount: MountedContentRoot): MountedContentRoot {
 21	    const key = createRegistryKey(mount.moduleId, mount.anchorKey);
 22	    const existing = this.mounts.get(key);
 23	
 24	    if (
