 27	  contentScripts: readonly ContentScriptConfig[] | undefined,
 28	  configDir: string,
 29	  extensionTargets?: readonly BrowserTarget[]
 30	): Promise<readonly ResolvedContentScriptConfig[]> {
 31	  if (!contentScripts || contentScripts.length === 0) {
 32	    return [];
 33	  }
 34	
 35	  const resolvedScripts: ResolvedContentScriptConfig[] = [];
 36	  const seenIds = new Set<string>();
 37	
 38	  for (const contentScript of contentScripts) {
 39	    validateContentScriptShape(contentScript, extensionTargets);
