 57	      )
 58	    );
 59	
 60	    const resolvedCss: string[] = [];
 61	    for (const cssPath of contentScript.css ?? []) {
 62	      const resolvedCssPath = path.resolve(configDir, cssPath);
 63	      await assertFileExists(
 64	        resolvedCssPath,
 65	        createExtfnError(
 66	          'E_ENTRY_NOT_FOUND',
 67	          `Missing content style: ${cssPath}`,
 68	          { id: contentScript.id, entry: cssPath }
 69	        )
 70	      );
 71	      resolvedCss.push(resolvedCssPath);
 72	    }
 73	
 74	    resolvedScripts.push({
 75	      ...contentScript,
 76	      resolvedEntry,
 77	      resolvedCss,
 78	    });
 79	  }
 80	
 81	  return resolvedScripts;
 82	}
 83	
 84	export function validateContentScriptShape(
 85	  contentScript: ContentScriptConfig,
 86	  extensionTargets?: readonly BrowserTarget[]
 87	): ContentScriptConfig {
 88	  if (typeof contentScript.id !== 'string' || contentScript.id.trim() === '') {
 89	    throw createExtfnError(
 90	      'E_CONFIG_INVALID',
 91	      'Content script id must be a non-empty string.'
 92	    );
 93	  }
 94	
 95	  if (typeof contentScript.entry !== 'string' || contentScript.entry.trim() === '') {
 96	    throw createExtfnError(
 97	      'E_CONFIG_INVALID',
 98	      `Content script ${contentScript.id} must include a non-empty entry.`
 99	    );
100	  }
101	
102	  if (!Array.isArray(contentScript.matches) || contentScript.matches.length === 0) {
103	    throw createExtfnError(
104	      'E_CONFIG_INVALID',
105	      `Content script ${contentScript.id} must include at least one match pattern.`
106	    );
107	  }
108	
109	  if (
110	    contentScript.styleIsolation !== undefined &&
111	    !ALLOWED_STYLE_ISOLATION.has(contentScript.styleIsolation)
112	  ) {
113	    throw createExtfnError(
114	      'E_CONFIG_INVALID',
115	      `Unsupported styleIsolation mode: ${contentScript.styleIsolation}`,
116	      { id: contentScript.id, styleIsolation: contentScript.styleIsolation }
117	    );
118	  }
119	
120	  if (contentScript.targets !== undefined) {
121	    if (!Array.isArray(contentScript.targets) || contentScript.targets.length === 0) {
122	      throw createExtfnError(
123	        'E_CONFIG_INVALID',
124	        `Content script ${contentScript.id} targets must contain at least one browser target.`
125	      );
126	    }
127	
128	    const extensionTargetSet = extensionTargets
129	      ? new Set<BrowserTarget>(extensionTargets)
130	      : undefined;
131	
132	    for (const target of contentScript.targets) {
133	      if (!SUPPORTED_BROWSER_TARGETS.includes(target)) {
134	        throw createExtfnError(
135	          'E_CONFIG_INVALID',
136	          `Content script ${contentScript.id} contains unsupported target: ${target}`,
137	          { id: contentScript.id, target }
138	        );
139	      }
140	
141	      if (extensionTargetSet && !extensionTargetSet.has(target)) {
142	        throw createExtfnError(
143	          'E_CONFIG_INVALID',
144	          `Content script ${contentScript.id} target is not listed in extension.targets: ${target}`,
145	          { id: contentScript.id, target }
146	        );
147	      }
148	    }
149	  }
150	
151	  return contentScript;
152	}
