249	  async *stream(
250	    input: string | Message[],
251	    options: {
252	      metadata?: Record<string, unknown>;
253	      timeout?: number;
254	      cancelToken?: CancellationToken;
255	    } = {}
256	  ): AsyncIterable<StreamEvent> {
257	    const traceId = randomTraceId();
258	    const tracer = this.resolveTracer();
259	    const span = tracer && this.config.observability?.enabled
260	      ? await tracer.span(SPAN_TYPES.PROVIDER_STREAM, {
261	          traceId,
262	          metadata: {
