385	  async completeBatch(
386	    requests: Array<BatchRequest | string>,
387	    options: {
388	      concurrency?: number;
389	      timeout?: number;
390	      partialResults?: boolean;
391	      retry?: RetryConfig;
392	    } = {}
393	  ): Promise<BatchResult[]> {
394	    const concurrency = options.concurrency ?? 5;
395	    const partialResults = options.partialResults ?? true;
396	    if (concurrency < 1) {
397	      throw new ValidationError("completeBatch() requires concurrency >= 1");
398	    }
399	
400	    const normalized = requests.map((request) =>
401	      typeof request === "string" ? ({ prompt: request } satisfies BatchRequest) : request
402	    );
403	    const outcomes = await mapWithConcurrency(normalized, concurrency, async (request) =>
404	      this.complete(request.prompt, {
405	        metadata: request.metadata,
406	        timeout: options.timeout,
407	        retry: options.retry
408	      })
409	    );
410	
411	    const results = outcomes.map((outcome, index) => {
412	      if (outcome instanceof Error) {
413	        const error = normalizeUnknownError(outcome);
414	        return {
415	          ok: false,
416	          index,
417	          error: {
418	            code: error.code,
419	            message: error.message
420	          }
421	        } satisfies BatchResult;
422	      }
423	      return {
424	        ok: true,
425	        index,
426	        content: outcome.content,
427	        traceId: outcome.traceId,
428	        trace_id: outcome.trace_id,
429	        response: outcome
430	      } satisfies BatchResult;
431	    });
432	
433	    if (!partialResults) {
434	      const failureIndex = outcomes.findIndex((outcome) => outcome instanceof Error);
435	      if (failureIndex >= 0) {
436	        throw normalizeUnknownError(outcomes[failureIndex]);
437	      }
438	    }
439	    return results;
