    71	      "Content-Type": "application/json",
    72	      ...headers,
    73	    };
    74	
    75	    if (auth?.token) {
    76	      requestHeaders["Authorization"] = `Bearer ${auth.token}`;
    77	    }
    78	    if (auth?.secretHeader) {
    79	      requestHeaders[auth.secretHeader] = auth.token || "";
    80	    }
    81	
    82	    const controller = new AbortController();
    83	    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    84	
    85	    let lastError: Error | null = null;
    86	
    87	    for (let attempt = 0; attempt < attempts; attempt++) {
    88	      try {
    89	        const response = await fetch(url, {
    90	          method: "POST",
    91	          headers: requestHeaders,
    92	          body: JSON.stringify({ events }),
    93	          signal: controller.signal,
    94	        });
