   112	        clearTimeout(timeoutId);
   113	        lastError = error as Error;
   114	
   115	        // Don't retry on abort
   116	        if (lastError.name === "AbortError") {
   117	          throw lastError;
   118	        }
   119	      }
   120	
   121	      // Exponential backoff with jitter
   122	      if (attempt < attempts - 1) {
   123	        const delay = backoffMs * Math.pow(2, attempt) + Math.random() * 100;
