    20	/**
    21	 * Create a WatchFn logs ingest handler
    22	 * Route: POST /watch/logs
    23	 * Body: { events: LogEvent[] }
    24	 */
    25	export function watchLogsHandler(options: WatchLogsHandlerOptions = {}) {
