     5	import type { Logger } from "../core/logger.js";
     6	
     7	/**
     8	 * Capture browser window errors and unhandled promise rejections
     9	 */
    10	export function captureBrowserErrors(logger: Logger): () => void {
    11	  if (typeof window === "undefined") {
    12	    throw new Error(
    13	      "captureBrowserErrors can only be used in browser environments"
    14	    );
    15	  }
    16	
    17	  const errorHandler = (event: ErrorEvent) => {
    18	    logger.error(
    19	      "Uncaught error",
    20	      {
    21	        message: event.message,
    22	        filename: event.filename,
    23	        lineno: event.lineno,
    24	        colno: event.colno,
    25	        stack: event.error?.stack,
    26	      },
    27	      ["browser-error", "uncaught"]
    28	    );
    29	  };
    30	
    31	  const rejectionHandler = (event: PromiseRejectionEvent) => {
    32	    logger.error(
    33	      "Unhandled promise rejection",
    34	      {
    35	        reason:
    36	          event.reason instanceof Error
    37	            ? {
    38	                message: event.reason.message,
    39	                stack: event.reason.stack,
    40	              }
    41	            : event.reason,
    42	      },
    43	      ["browser-error", "unhandled-rejection"]
    44	    );
    45	  };
    46	
    47	  window.addEventListener("error", errorHandler);
    48	  window.addEventListener("unhandledrejection", rejectionHandler);
    49	
    50	  // Return cleanup function
    51	  return () => {
    52	    window.removeEventListener("error", errorHandler);
    53	    window.removeEventListener("unhandledrejection", rejectionHandler);
    54	  };
    55	}
    56	
    57	/**
    58	 * Attach flush hooks for browser unload events
    59	 */
    60	export function attachFlushHooks(logger: Logger): () => void {
    61	  if (typeof window === "undefined") {
    62	    throw new Error(
    63	      "attachFlushHooks can only be used in browser environments"
    64	    );
    65	  }
    66	
    67	  const visibilityHandler = () => {
    68	    if (document.visibilityState === "hidden") {
    69	      logger.flush().catch((error) => {
    70	        console.error("[logfn] Failed to flush on visibility change", error);
    71	      });
    72	    }
    73	  };
    74	
    75	  const unloadHandler = () => {
    76	    // Try to flush synchronously (may not complete)
    77	    logger.flush().catch(() => {
    78	      // Best effort
    79	    });
    80	  };
    81	
    82	  window.addEventListener("visibilitychange", visibilityHandler);
    83	  window.addEventListener("beforeunload", unloadHandler);
    84	
    85	  return () => {
    86	    window.removeEventListener("visibilitychange", visibilityHandler);
