  1	/**
  2	 * Redaction pipeline stage
  3	 */
  4	
  5	import type { LogEvent, PipelineStage } from "../types.js";
  6	
  7	/**
  8	 * Redaction options
  9	 */
 10	export interface RedactionOptions {
 11	  /** Patterns to redact (default: common secrets) */
 12	  patterns?: RegExp[];
 13	
 14	  /** Allowlist of keys to skip redaction */
 15	  allowlist?: string[];
 16	}
 17	
 18	/**
 19	 * Default secret patterns
 20	 */
 21	const DEFAULT_PATTERNS = [
 22	  /api[_-]?key[_-]?=?[\w-]+/gi,
 23	  /token[_-]?=?[\w-]+/gi,
 24	  /password[_-]?=?[\w-]+/gi,
 25	  /authorization:\s*\S+/gi,
 26	  /bearer\s+[\w-]+/gi,
 27	  /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, // Email
 28	];
 29	
 30	/**
 31	 * Redact a string value
 32	 */
 33	function redactString(value: string, patterns: RegExp[]): string {
 34	  let result = value;
 35	  for (const pattern of patterns) {
 36	    result = result.replace(pattern, "[redacted]");
 37	  }
 38	  return result;
 39	}
 40	
 41	/**
 42	 * Redact object values recursively
 43	 */
 44	function redactValue(
 45	  value: unknown,
 46	  patterns: RegExp[],
 47	  allowlist: Set<string>,
 48	  path = ""
 49	): unknown {
 50	  if (typeof value === "string") {
 51	    return allowlist.has(path) ? value : redactString(value, patterns);
 52	  }
 53	
 54	  if (Array.isArray(value)) {
 55	    return value.map((item, i) =>
 56	      redactValue(item, patterns, allowlist, `${path}[${i}]`)
 57	    );
 58	  }
 59	
 60	  if (value && typeof value === "object") {
 61	    const result: Record<string, unknown> = {};
 62	    for (const [key, val] of Object.entries(value)) {
 63	      const newPath = path ? `${path}.${key}` : key;
 64	      result[key] = redactValue(val, patterns, allowlist, newPath);
 65	    }
 66	    return result;
 67	  }
 68	
 69	  return value;
 70	}
 71	
 72	/**
 73	 * Create a redaction pipeline stage
 74	 */
 75	export function redactSecFn(options: RedactionOptions = {}): PipelineStage {
 76	  const patterns = options.patterns ?? DEFAULT_PATTERNS;
 77	  const allowlist = new Set(options.allowlist ?? []);
 78	
 79	  return (event: LogEvent): LogEvent => {
 80	    const redacted: LogEvent = {
 81	      ...event,
 82	      msg: redactString(event.msg, patterns),
 83	    };
 84	
 85	    // Redact context
 86	    if (event.ctx) {
 87	      redacted.ctx = redactValue(event.ctx, patterns, allowlist) as Record<
 88	        string,
 89	        unknown
 90	      >;
 91	    }
 92	
 93	    // Redact IDs if not allowlisted
 94	    if (event.userId && !allowlist.has("userId")) {
 95	      redacted.userId = redactString(event.userId, patterns);
 96	    }
 97	    if (event.tenantId && !allowlist.has("tenantId")) {
 98	      redacted.tenantId = redactString(event.tenantId, patterns);
 99	    }
100	
101	    return redacted;
102	  };
103	}
  1	/**
  2	 * Request ID and trace context pipeline stage
  3	 */
  4	
  5	import type { LogEvent, PipelineStage } from "../types.js";
  6	
  7	/**
  8	 * Request ID options
  9	 */
 10	export interface RequestIdOptions {
 11	  /** Header name containing W3C TraceContext (default: 'traceparent') */
 12	  header?: string;
 13	
 14	  /** Custom ID generator function */
 15	  generate?: () => { traceId?: string; spanId?: string; requestId?: string };
 16	}
 17	
 18	/**
 19	 * Parse W3C TraceContext traceparent header
 20	 * Format: version-traceId-spanId-flags
 21	 * Example: 00-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-01
 22	 */
 23	function parseTraceParent(
 24	  traceparent: string
 25	): { traceId: string; spanId: string } | null {
 26	  const parts = traceparent.split("-");
 27	  if (parts.length !== 4) {
 28	    return null;
 29	  }
 30	
 31	  const [version, traceId, spanId] = parts;
 32	
 33	  // Version must be 00 for now
 34	  if (version !== "00") {
 35	    return null;
 36	  }
 37	
 38	  // Validate format
 39	  if (traceId.length !== 32 || spanId.length !== 16) {
 40	    return null;
 41	  }
 42	
 43	  return { traceId, spanId };
 44	}
 45	
 46	/**
 47	 * Generate a random hex string
 48	 */
 49	function randomHex(bytes: number): string {
 50	  if (typeof crypto !== "undefined" && crypto.randomUUID) {
 51	    // Use crypto.randomUUID and convert to hex
 52	    return crypto
 53	      .randomUUID()
 54	      .replace(/-/g, "")
 55	      .slice(0, bytes * 2);
 56	  }
 57	
 58	  // Fallback for older environments
 59	  const hex = "0123456789abcdef";
 60	  let result = "";
 61	  for (let i = 0; i < bytes * 2; i++) {
 62	    result += hex[Math.floor(Math.random() * 16)];
 63	  }
 64	  return result;
 65	}
 66	
 67	/**
 68	 * Default ID generator
 69	 */
 70	function defaultGenerate(): {
 71	  traceId: string;
 72	  spanId: string;
 73	  requestId: string;
 74	} {
 75	  return {
 76	    traceId: randomHex(16), // 32 hex chars
 77	    spanId: randomHex(8), // 16 hex chars
 78	    requestId: randomHex(16),
 79	  };
 80	}
 81	
 82	/**
 83	 * Create a request ID pipeline stage
 84	 */
 85	export function withRequestIds(options: RequestIdOptions = {}): PipelineStage {
 86	  const generate = options.generate ?? defaultGenerate;
 87	
 88	  return (event: LogEvent): LogEvent => {
 89	    // If event already has IDs, don't override
 90	    if (event.traceId || event.spanId || event.requestId) {
 91	      return event;
 92	    }
 93	
 94	    // Try to parse from header if available (in practice this would come from context)
 95	    // For now, just generate new IDs
 96	    const ids = generate();
 97	
 98	    return {
 99	      ...event,
100	      traceId: ids.traceId ?? event.traceId,
101	      spanId: ids.spanId ?? event.spanId,
102	      requestId: ids.requestId ?? event.requestId,
103	    };
104	  };
105	}
106	
107	/**
108	 * Parse W3C TraceContext from traceparent header value
109	 * Exported for use in middleware
110	 */
111	export function parseW3CTraceContext(
112	  traceparent: string
113	): { traceId: string; spanId: string } | null {
114	  return parseTraceParent(traceparent);
115	}
  1	/**
  2	 * Sampling pipeline stage
  3	 */
  4	
  5	import type { LogEvent, LogLevel, PipelineStage } from "../types.js";
  6	
  7	/**
  8	 * Sampling rates per log level (0-1, where 1 = keep all)
  9	 */
 10	export type SamplingRates = Partial<Record<LogLevel, number>>;
 11	
 12	/**
 13	 * Default sampling rates
 14	 */
 15	const DEFAULT_RATES: SamplingRates = {
 16	  error: 1.0,
 17	  fatal: 1.0,
 18	  warn: 1.0,
 19	  info: 0.1,
 20	  debug: 0.01,
 21	  trace: 0.0,
 22	};
 23	
 24	/**
 25	 * Create a sampling pipeline stage
 26	 * Returns null to drop events based on sampling rate
 27	 */
 28	export function sample(rates: SamplingRates = {}): PipelineStage {
 29	  const mergedRates = { ...DEFAULT_RATES, ...rates };
 30	
 31	  return (event: LogEvent): LogEvent | null => {
 32	    const rate = mergedRates[event.level] ?? 1.0;
 33	
 34	    // Always keep if rate is 1
 35	    if (rate >= 1.0) {
 36	      return event;
 37	    }
 38	
 39	    // Always drop if rate is 0
 40	    if (rate <= 0.0) {
 41	      return null;
 42	    }
 43	
 44	    // Sample based on rate
 45	    if (Math.random() < rate) {
 46	      return event;
 47	    }
 48	
 49	    return null; // Drop event
 50	  };
 51	}
  1	/**
  2	 * HTTP sink for batched log transport
  3	 */
  4	
  5	import type { LogEvent, Sink } from "../types.js";
  6	
  7	/**
  8	 * HTTP sink options
  9	 */
 10	export interface HttpSinkOptions {
 11	  /** Target URL for log ingestion */
 12	  url: string;
 13	
 14	  /** Batch size before flushing (default: 50) */
 15	  batch?: number;
 16	
 17	  /** Flush interval in milliseconds (default: 1000) */
 18	  flushIntervalMs?: number;
 19	
 20	  /** Request timeout in milliseconds (default: 3000) */
 21	  timeoutMs?: number;
 22	
 23	  /** Additional headers */
 24	  headers?: Record<string, string>;
 25	
 26	  /** Authentication */
 27	  auth?: {
 28	    token?: string;
 29	    secretHeader?: string;
 30	  };
 31	
 32	  /** Retry configuration */
 33	  retry?: {
 34	    attempts?: number;
 35	    backoffMs?: number;
 36	  };
 37	
 38	  /** Offline buffer strategy */
 39	  offlineBuffer?: "memory" | "indexeddb";
 40	
 41	  /** Maximum queue size (default: 5000) */
 42	  maxQueue?: number;
 43	}
 44	
 45	/**
 46	 * Create an HTTP sink
 47	 */
 48	export function sinkHttp(options: HttpSinkOptions): Sink {
 49	  const {
 50	    url,
 51	    batch: batchSize = 50,
 52	    flushIntervalMs = 1000,
 53	    timeoutMs = 3000,
 54	    headers = {},
 55	    auth,
 56	    retry = {},
 57	    maxQueue = 5000,
 58	  } = options;
 59	
 60	  const { attempts = 5, backoffMs = 200 } = retry;
 61	
 62	  let buffer: LogEvent[] = [];
 63	  let flushTimer: ReturnType<typeof setTimeout> | null = null;
 64	  let flushing = false;
 65	
 66	  /**
 67	   * Send events to the HTTP endpoint with retry
 68	   */
 69	  async function sendBatch(events: LogEvent[]): Promise<void> {
 70	    const requestHeaders: Record<string, string> = {
 71	      "Content-Type": "application/json",
 72	      ...headers,
 73	    };
 74	
 75	    if (auth?.token) {
 76	      requestHeaders["Authorization"] = `Bearer ${auth.token}`;
 77	    }
 78	    if (auth?.secretHeader) {
 79	      requestHeaders[auth.secretHeader] = auth.token || "";
 80	    }
 81	
 82	    const controller = new AbortController();
 83	    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
 84	
 85	    let lastError: Error | null = null;
 86	
 87	    for (let attempt = 0; attempt < attempts; attempt++) {
 88	      try {
 89	        const response = await fetch(url, {
 90	          method: "POST",
 91	          headers: requestHeaders,
 92	          body: JSON.stringify({ events }),
 93	          signal: controller.signal,
 94	        });
 95	
 96	        clearTimeout(timeoutId);
 97	
 98	        if (response.ok) {
 99	          return; // Success
100	        }
101	
102	        // Don't retry on client errors
103	        if (response.status >= 400 && response.status < 500) {
104	          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
105	        }
106	
107	        // Retry on server errors
108	        lastError = new Error(
109	          `HTTP ${response.status}: ${response.statusText}`
110	        );
111	      } catch (error) {
112	        clearTimeout(timeoutId);
113	        lastError = error as Error;
114	
115	        // Don't retry on abort
116	        if (lastError.name === "AbortError") {
117	          throw lastError;
118	        }
119	      }
120	
121	      // Exponential backoff with jitter
122	      if (attempt < attempts - 1) {
123	        const delay = backoffMs * Math.pow(2, attempt) + Math.random() * 100;
124	        await new Promise((resolve) => setTimeout(resolve, delay));
125	      }
126	    }
127	
128	    throw lastError || new Error("Unknown error");
129	  }
130	
131	  /**
132	   * Flush buffered events
133	   */
134	  async function flushBuffer(): Promise<void> {
135	    if (flushing || buffer.length === 0) {
136	      return;
137	    }
138	
139	    flushing = true;
140	    const toSend = buffer.splice(0, buffer.length);
141	
142	    try {
143	      await sendBatch(toSend);
144	    } catch (error) {
145	      // On error, put events back at the front (up to maxQueue)
146	      const putBack = toSend.slice(0, Math.max(0, maxQueue - buffer.length));
147	      buffer.unshift(...putBack);
148	
149	      // Log error internally (without recursion)
150	      console.error("[logfn http-sink error]", error);
151	    } finally {
152	      flushing = false;
153	    }
154	  }
155	
156	  /**
157	   * Schedule a flush
158	   */
159	  function scheduleFlush(): void {
160	    if (flushTimer) {
161	      return;
162	    }
163	
164	    flushTimer = setTimeout(() => {
165	      flushTimer = null;
166	      flushBuffer().catch(() => {
167	        // Error already handled in flushBuffer
168	      });
169	    }, flushIntervalMs);
170	  }
171	
172	  /**
173	   * Add events to browser flush hooks
174	   */
175	  if (typeof window !== "undefined") {
176	    window.addEventListener("visibilitychange", () => {
177	      if (document.visibilityState === "hidden") {
178	        flushBuffer().catch(() => {});
179	      }
180	    });
181	
182	    window.addEventListener("beforeunload", () => {
183	      // Synchronous flush attempt (may not complete)
184	      if (buffer.length > 0) {
185	        // Use sendBeacon if available
186	        if (navigator.sendBeacon) {
187	          const blob = new Blob([JSON.stringify({ events: buffer })], {
188	            type: "application/json",
189	          });
190	          navigator.sendBeacon(url, blob);
191	        }
192	      }
193	    });
194	  }
195	
196	  const sink: Sink = (batch: LogEvent[]) => {
197	    // Add to buffer
198	    buffer.push(...batch);
199	
200	    // Drop oldest if over limit
201	    if (buffer.length > maxQueue) {
202	      const excess = buffer.length - maxQueue;
203	      buffer.splice(0, excess);
204	    }
205	
206	    // Flush if batch size reached
207	    if (buffer.length >= batchSize) {
208	      flushBuffer().catch(() => {});
209	    } else {
210	      scheduleFlush();
211	    }
212	  };
213	
214	  sink.flush = async (): Promise<void> => {
215	    if (flushTimer) {
216	      clearTimeout(flushTimer);
217	      flushTimer = null;
218	    }
219	    await flushBuffer();
220	  };
221	
222	  return sink;
223	}
  1	/**
  2	 * Express middleware adapter for request logging
  3	 */
  4	
  5	import type { Request, Response, NextFunction } from "express";
  6	import type { RequestLoggerOptions } from "./middleware.js";
  7	import {
  8	  extractCorrelationIds,
  9	  redactHeaders,
 10	  truncateBody,
 11	} from "./middleware.js";
 12	
 13	/**
 14	 * Create Express request logger middleware
 15	 */
 16	export function requestLogger(options: RequestLoggerOptions = {}) {
 17	  const {
 18	    header = "traceparent",
 19	    redactHeaders: redactList = [],
 20	    logger,
 21	    includeBody = false,
 22	    captureUser,
 23	  } = options;
 24	
 25	  return (req: Request, res: Response, next: NextFunction) => {
 26	    const startTime = Date.now();
 27	
 28	    // Extract correlation IDs
 29	    const ids = extractCorrelationIds(req.headers, header);
 30	
 31	    // Create child logger with correlation IDs
 32	    const requestLogger = logger
 33	      ? logger.child({
 34	          ctx: {
 35	            traceId: ids.traceId,
 36	            spanId: ids.spanId,
 37	            requestId: ids.requestId,
 38	          },
 39	        })
 40	      : undefined;
 41	
 42	    // Attach logger to request
 43	    (req as any).log = requestLogger;
 44	
 45	    // Capture user/tenant if provided
 46	    let userId: string | undefined;
 47	    let tenantId: string | undefined;
 48	    if (captureUser) {
 49	      const userInfo = captureUser(req);
 50	      userId = userInfo?.userId;
 51	      tenantId = userInfo?.tenantId;
 52	    }
 53	
 54	    // Log request start
 55	    if (requestLogger) {
 56	      requestLogger.info("Request started", {
 57	        method: req.method,
 58	        url: req.url,
 59	        path: req.path,
 60	        headers: redactHeaders(req.headers, redactList),
 61	        query: req.query,
 62	        userId,
 63	        tenantId,
 64	        body: includeBody ? truncateBody(req.body) : undefined,
 65	      });
 66	    }
 67	
 68	    // Capture response finish
 69	    const originalEnd = res.end;
 70	    res.end = function (this: Response, ...args: any[]): any {
 71	      const latencyMs = Date.now() - startTime;
 72	
 73	      // Log response
 74	      if (requestLogger) {
 75	        requestLogger.info("Request completed", {
 76	          method: req.method,
 77	          url: req.url,
 78	          path: req.path,
 79	          statusCode: res.statusCode,
 80	          contentLength: res.get("content-length"),
 81	          latencyMs,
 82	          userId,
 83	          tenantId,
 84	        });
 85	      }
 86	
 87	      return originalEnd.apply(this, args as any);
 88	    };
 89	
 90	    next();
 91	  };
 92	}
 93	
