 95	export type { RequestLoggerOptions } from "./middleware.js";
  1	/**
  2	 * Fastify plugin for request logging
  3	 */
  4	
  5	import type {
  6	  FastifyRequest,
  7	  FastifyReply,
  8	  FastifyPluginCallback,
  9	} from "fastify";
 10	import type { RequestLoggerOptions } from "./middleware.js";
 11	import {
 12	  extractCorrelationIds,
 13	  redactHeaders,
 14	  truncateBody,
 15	} from "./middleware.js";
 16	
 17	/**
 18	 * Create Fastify request logger plugin
 19	 */
 20	export function requestLogger(
 21	  options: RequestLoggerOptions = {}
 22	): FastifyPluginCallback {
 23	  const {
 24	    header = "traceparent",
 25	    redactHeaders: redactList = [],
 26	    logger,
 27	    includeBody = false,
 28	    captureUser,
 29	  } = options;
 30	
 31	  return (fastify, _opts, done) => {
 32	    fastify.addHook("onRequest", async (request: FastifyRequest) => {
 33	      const startTime = Date.now();
 34	
 35	      // Extract correlation IDs
 36	      const ids = extractCorrelationIds(request.headers, header);
 37	
 38	      // Create child logger with correlation IDs
 39	      const requestLogger = logger
 40	        ? logger.child({
 41	            ctx: {
 42	              traceId: ids.traceId,
 43	              spanId: ids.spanId,
 44	              requestId: ids.requestId,
 45	            },
 46	          })
 47	        : undefined;
 48	
 49	      // Attach logger to request
 50	      (request as any).log = requestLogger;
 51	
 52	      // Store start time for latency calculation
 53	      (request as any)._startTime = startTime;
 54	
 55	      // Capture user/tenant if provided
 56	      let userId: string | undefined;
 57	      let tenantId: string | undefined;
 58	      if (captureUser) {
 59	        const userInfo = captureUser(request);
 60	        userId = userInfo?.userId;
 61	        tenantId = userInfo?.tenantId;
 62	      }
 63	
 64	      // Store user info
 65	      (request as any)._userId = userId;
 66	      (request as any)._tenantId = tenantId;
 67	
 68	      // Log request start
 69	      if (requestLogger) {
 70	        requestLogger.info("Request started", {
 71	          method: request.method,
 72	          url: request.url,
 73	          headers: redactHeaders(request.headers, redactList),
 74	          query: request.query,
 75	          userId,
 76	          tenantId,
 77	          body: includeBody ? truncateBody(request.body) : undefined,
 78	        });
 79	      }
 80	    });
 81	
 82	    fastify.addHook(
 83	      "onResponse",
 84	      async (request: FastifyRequest, reply: FastifyReply) => {
 85	        const startTime = (request as any)._startTime || Date.now();
 86	        const latencyMs = Date.now() - startTime;
 87	        const requestLogger = (request as any).log;
 88	        const userId = (request as any)._userId;
 89	        const tenantId = (request as any)._tenantId;
 90	
 91	        // Log response
 92	        if (requestLogger) {
 93	          requestLogger.info("Request completed", {
 94	            method: request.method,
 95	            url: request.url,
 96	            statusCode: reply.statusCode,
 97	            contentLength: reply.getHeader("content-length"),
 98	            latencyMs,
 99	            userId,
100	            tenantId,
101	          });
102	        }
103	      }
104	    );
105	
106	    done();
107	  };
108	}
