  1	/**
  2	 * Hono middleware for request logging
  3	 */
  4	
  5	import type { Context, MiddlewareHandler } from "hono";
  6	import type { RequestLoggerOptions } from "./middleware.js";
  7	import {
  8	  extractCorrelationIds,
  9	  redactHeaders,
 10	  truncateBody,
 11	} from "./middleware.js";
 12	
 13	/**
 14	 * Create Hono request logger middleware
 15	 */
 16	export function requestLogger(
 17	  options: RequestLoggerOptions = {}
 18	): MiddlewareHandler {
 19	  const {
 20	    header = "traceparent",
 21	    redactHeaders: redactList = [],
 22	    logger,
 23	    includeBody = false,
 24	    captureUser,
 25	  } = options;
 26	
 27	  return async (c: Context, next) => {
 28	    const startTime = Date.now();
 29	    const req = c.req;
 30	
 31	    // Extract correlation IDs
 32	    const headersObj: Record<string, string> = {};
 33	    req.raw.headers.forEach((value, key) => {
 34	      headersObj[key] = value;
 35	    });
 36	
 37	    const ids = extractCorrelationIds(headersObj, header);
 38	
 39	    // Create child logger with correlation IDs
 40	    const requestLogger = logger
 41	      ? logger.child({
 42	          ctx: {
 43	            traceId: ids.traceId,
 44	            spanId: ids.spanId,
 45	            requestId: ids.requestId,
 46	          },
 47	        })
 48	      : undefined;
 49	
 50	    // Attach logger to context
 51	    c.set("log", requestLogger);
 52	
 53	    // Capture user/tenant if provided
 54	    let userId: string | undefined;
 55	    let tenantId: string | undefined;
 56	    if (captureUser) {
 57	      const userInfo = captureUser(c);
 58	      userId = userInfo?.userId;
 59	      tenantId = userInfo?.tenantId;
 60	    }
 61	
 62	    // Log request start
 63	    if (requestLogger) {
 64	      requestLogger.info("Request started", {
 65	        method: req.method,
 66	        url: req.url,
 67	        path: req.path,
 68	        headers: redactHeaders(headersObj, redactList),
 69	        query: req.query(),
 70	        userId,
