     8	
     9	export class ConflictResolver {
    10	  private llm: LLMProvider;
    11	
    12	  constructor(llm: LLMProvider) {
    13	    this.llm = llm;
    14	  }
    15	
    16	  async resolve(newFact: string, existingMemory: Memory): Promise<ResolutionResult> {
    17	    const prompt = `
    18	    Compare the following two pieces of information and determine their relationship.
    19	    
    20	    Existing Fact: "${existingMemory.content}"
    21	    New Fact: "${newFact}"
    22	    
    23	    Determine if the New Fact:
    24	    - "updates": Supersedes the Existing Fact (e.g., "I live in NY" vs "I moved to SF").
    25	    - "extends": Adds detail to the Existing Fact without conflict.
    26	    - "contradicts": Directly conflicts with the Existing Fact (e.g., "I like red" vs "I hate red").
    27	    - "none": No direct relationship or unrelated.
    28	    
    29	    Return JSON:
    30	    {
    31	      "type": "updates" | "extends" | "contradicts" | "none",
    32	      "reasoning": "Short explanation"
