     1	import { Segment, SegmentRule, UserTraits, Operator } from '../types';
     2	
     3	export class SegmentEvaluator {
     4	  private segments: Map<string, Segment> = new Map();
     5	
     6	  constructor(segments: Segment[] = []) {
     7	    segments.forEach(s => this.segments.set(s.id, s));
     8	  }
     9	
    10	  setSegments(segments: Segment[]) {
    11	    this.segments.clear();
    12	    segments.forEach(s => this.segments.set(s.id, s));
    13	  }
    14	
    15	  evaluate(segmentId: string, traits: UserTraits): boolean {
    16	    const segment = this.segments.get(segmentId);
    17	    if (!segment) {
    18	      // If segment is missing, fail closed (false)
    19	      // or should we log a warning?
    20	      return false;
    21	    }
    22	    return this.matchesSegment(segment, traits);
    23	  }
    24	
    25	  matchesSegment(segment: Segment, traits: UserTraits): boolean {
    26	    if (!segment.rules || segment.rules.length === 0) {
    27	      return true; // Empty segment matches everyone? Or no-one? Usually everyone if used as a filter.
    28	    }
    29	
    30	    const matchType = segment.matchType || 'all';
    31	
    32	    if (matchType === 'any') {
    33	      return segment.rules.some(rule => this.matchesRule(rule, traits));
    34	    } else {
    35	      return segment.rules.every(rule => this.matchesRule(rule, traits));
    36	    }
    37	  }
    38	
    39	  matchesRule(rule: SegmentRule, traits: UserTraits): boolean {
    40	    const traitValue = traits[rule.field];
    41	    const { operator, value } = rule;
    42	
    43	    switch (operator) {
    44	      case 'exists':
    45	        return traitValue !== undefined && traitValue !== null;
    46	      case 'does_not_exist':
    47	        return traitValue === undefined || traitValue === null;
    48	      
    49	      // If trait is missing for other operators, usually evaluate to false
    50	      // unless comparing inequality might be tricky.
    51	      // For now, if trait is missing, we return false for most checks.
    52	    }
    53	
    54	    if (traitValue === undefined || traitValue === null) return false;
    55	
    56	    switch (operator) {
    57	      case 'equals':
    58	        return String(traitValue) === String(value);
    59	      case 'does_not_equal':
    60	        return String(traitValue) !== String(value);
    61	      case 'contains':
    62	        return String(traitValue).includes(String(value));
    63	      case 'does_not_contain':
    64	        return !String(traitValue).includes(String(value));
    65	      case 'in':
    66	        return Array.isArray(value) && value.includes(traitValue);
    67	      case 'not_in':
    68	        return Array.isArray(value) && !value.includes(traitValue);
    69	      case 'gt':
    70	        return Number(traitValue) > Number(value);
    71	      case 'gte':
