     5	class SegmentEvaluator:
     6	    def __init__(self, segments: Optional[List[Segment]] = None):
     7	        self.segments: Dict[str, Segment] = {}
     8	        if segments:
     9	            for s in segments:
    10	                self.segments[s.id] = s
    11	
    12	    def set_segments(self, segments: List[Segment]):
    13	        self.segments.clear()
    14	        for s in segments:
    15	            self.segments[s.id] = s
    16	
    17	    def evaluate(self, segment_id: str, traits: UserTraits) -> bool:
    18	        segment = self.segments.get(segment_id)
    19	        if not segment:
    20	            return False
    21	        return self.matches_segment(segment, traits)
    22	
    23	    def matches_segment(self, segment: Segment, traits: UserTraits) -> bool:
    24	        if not segment.rules:
    25	            return True
    26	        
    27	        match_type = segment.match_type or 'all'
    28	        
    29	        if match_type == 'any':
    30	            return any(self.matches_rule(rule, traits) for rule in segment.rules)
    31	        else:
    32	            return all(self.matches_rule(rule, traits) for rule in segment.rules)
    33	
    34	    def matches_rule(self, rule: SegmentRule, traits: UserTraits) -> bool:
    35	        trait_value = traits.get(rule.field)
    36	        operator = rule.operator
    37	        value = rule.value
    38	
    39	        if operator == 'exists':
    40	            return trait_value is not None
    41	        
    42	        if operator == 'does_not_exist':
    43	            return trait_value is None
    44	
    45	        if trait_value is None:
    46	            return False
    47	
    48	        # Convert to string for string comparisons if needed, 
    49	        # but keep original type for numbers if possible.
    50	        
    51	        str_trait = str(trait_value)
    52	        str_value = str(value) if value is not None else ""
    53	
    54	        if operator == 'equals':
    55	            return str_trait == str_value
    56	        
    57	        if operator == 'does_not_equal':
    58	            return str_trait != str_value
    59	        
    60	        if operator == 'contains':
    61	            return str_value in str_trait
    62	        
    63	        if operator == 'does_not_contain':
    64	            return str_value not in str_trait
    65	        
    66	        if operator == 'in':
    67	            return isinstance(value, list) and trait_value in value
    68	        
    69	        if operator == 'not_in':
    70	            return isinstance(value, list) and trait_value not in value
    71	        
    72	        # Numeric comparisons
    73	        if operator in ('gt', 'gte', 'lt', 'lte'):
    74	            try:
    75	                num_trait = float(trait_value)
    76	                num_value = float(value)
    77	                
    78	                if operator == 'gt': return num_trait > num_value
    79	                if operator == 'gte': return num_trait >= num_value
    80	                if operator == 'lt': return num_trait < num_value
    81	                if operator == 'lte': return num_trait <= num_value
    82	            except (ValueError, TypeError):
    83	                return False
    84	
    85	        if operator == 'regex':
    86	            try:
    87	                return bool(re.search(str_value, str_trait))
    88	            except re.error:
    89	                return False
    90	
    91	        return False
