     1	def fnv1a_hash(s: str) -> int:
     2	    """
     3	    Simple FNV-1a hash implementation for deterministic bucketing.
     4	    Match strict 32-bit unsigned integer wrapping behavior of TypeScript/JS.
     5	    """
     6	    hash_val = 0x811c9dc5
     7	    
     8	    # 32-bit mask
     9	    mask = 0xFFFFFFFF
    10	
    11	    for char in s:
    12	        # JS charCodeAt works on UTF-16 code units. 
    13	        # For standard ASCII/BMP, ord(char) corresponds well.
    14	        # Strict bitwise operations are needed to match JS behaviour.
    15	        
    16	        # hash ^= str.charCodeAt(i)
    17	        hash_val ^= ord(char)
    18	        hash_val &= mask
    19	        
    20	        # hash = Math.imul(hash, 0x01000193)
    21	        # Math.imul performs C-like 32-bit multiplication
    22	        hash_val = (hash_val * 0x01000193) & mask
    23	
    24	    # return hash >>> 0 (unsigned right shift)
    25	    # in Python, the mask already ensures we are within 32-bit range, 
    26	    # but we treat it as unsigned.
    27	    return hash_val
