  1	// Simple FNV-1a hash implementation for deterministic bucketing
  2	export function hash(str: string): number {
  3	  let hash = 0x811c9dc5;
  4	  for (let i = 0; i < str.length; i++) {
  5	    hash ^= str.charCodeAt(i);
  6	    hash = Math.imul(hash, 0x01000193);
  7	  }
  8	  return hash >>> 0; // Ensure unsigned 32-bit integer
  9	}
 10	
 11	export function getBucket(key: string, contextId: string, totalBuckets: number = 100): number {
 12	  const combined = `${key}:${contextId}`;
 13	  const h = hash(combined);
 14	  // Matches 0 to totalBuckets-1
 15	  return h % totalBuckets;
 16	}
