146	  async complete<TParsed = unknown>(
147	    prompt: string,
148	    options: {
149	      metadata?: Record<string, unknown>;
150	      timeout?: number;
151	      cancelToken?: CancellationToken;
152	      structured?: StructuredParser<TParsed>;
153	      structuredOutput?: StructuredParser<TParsed>;
154	      retry?: RetryConfig;
155	    } = {}
156	  ): Promise<CompletionResponse<TParsed>> {
157	    if (!prompt) {
158	      throw new ValidationError("complete() requires a non-empty prompt");
159	    }
160	    const request: CompletionRequest = { prompt, metadata: options.metadata };
161	    const traceId = randomTraceId();
162	
163	    return await this.runWithObservability("completion", traceId, request.metadata, async () => {
164	      const cacheKey = this.requireModel();
165	      const cached = await this.config.cache?.get(prompt, cacheKey.model, cacheKey.provider, request.metadata);
166	      if (cached) {
167	        return this.finalizeCompletion(cached, traceId, options.structuredOutput ?? options.structured);
168	      }
169	
170	      const response = await retryAsync(
171	        async () => {
172	          try {
173	            return await callWithTimeoutAndCancel(
174	              this.requireModel().complete(request),
175	              options.timeout,
176	              options.cancelToken
177	            );
178	          } catch (error) {
179	            throw normalizeUnknownError(error);
180	          }
181	        },
182	        options.retry ?? this.config.retry
183	      );
184	
185	      const finalized = this.finalizeCompletion(response, traceId, options.structuredOutput ?? options.structured);
186	      await this.config.cache?.set(prompt, cacheKey.model, cacheKey.provider, finalized, request.metadata);
187	      await this.persistTrace({
188	        kind: "completion",
189	        traceId,
190	        request: { prompt, metadata: request.metadata },
191	        response: finalized
192	      });
193	      return finalized;
194	    });
195	  }
