249	  async *stream(
250	    input: string | Message[],
251	    options: {
252	      metadata?: Record<string, unknown>;
253	      timeout?: number;
254	      cancelToken?: CancellationToken;
255	    } = {}
256	  ): AsyncIterable<StreamEvent> {
257	    const traceId = randomTraceId();
258	    const tracer = this.resolveTracer();
259	    const span = tracer && this.config.observability?.enabled
260	      ? await tracer.span(SPAN_TYPES.PROVIDER_STREAM, {
261	          traceId,
262	          metadata: {
263	            metadata: options.metadata ?? {},
264	            mode: Array.isArray(input) ? "chat" : "completion"
265	          }
266	        })
267	      : undefined;
268	    const streamedContent: string[] = [];
269	    let latestUsage: CompletionResponse["usage"];
270	
271	    try {
272	      if (typeof input === "string") {
273	        const stream = this.requireModel().stream({ prompt: input, metadata: options.metadata });
274	        for await (const event of normalizeStream(
275	          iterateWithTimeoutAndCancel(stream, options.timeout, options.cancelToken),
276	          traceId
277	        )) {
278	          if (event.type === "content") {
279	            streamedContent.push(event.delta);
280	          } else if (event.type === "token_usage") {
281	            latestUsage = {
282	              prompt_tokens: event.prompt_tokens,
283	              completion_tokens: event.completion_tokens,
284	              total_tokens: event.prompt_tokens + event.completion_tokens,
285	              promptTokens: event.prompt_tokens,
286	              completionTokens: event.completion_tokens,
287	              totalTokens: event.prompt_tokens + event.completion_tokens
288	            };
289	          }
290	          yield event;
291	        }
292	      } else {
293	        const response = this.finalizeChat(
294	          await retryAsync(
295	            async () =>
296	              callWithTimeoutAndCancel(
297	                this.requireModel().chat({
298	                  messages: input,
299	                  metadata: options.metadata
300	                }),
301	                options.timeout,
302	                options.cancelToken
303	              ),
304	            this.config.retry
305	          ),
306	          traceId
307	        );
308	        for await (const event of normalizeStream(
309	          (async function* (): AsyncIterable<StreamEvent> {
310	            yield {
311	              type: "content",
312	              content: response.message.content,
313	              delta: response.message.content
314	            };
315	            if (response.usage) {
316	              yield {
317	                type: "token_usage",
318	                prompt_tokens: response.usage.prompt_tokens,
319	                completion_tokens: response.usage.completion_tokens
320	              };
321	            }
322	            yield { type: "end", finish_reason: "stop" };
323	          })(),
324	          traceId
325	        )) {
326	          if (event.type === "content") {
327	            streamedContent.push(event.delta);
328	          } else if (event.type === "token_usage") {
329	            latestUsage = {
330	              prompt_tokens: event.prompt_tokens,
331	              completion_tokens: event.completion_tokens,
332	              total_tokens: event.prompt_tokens + event.completion_tokens,
333	              promptTokens: event.prompt_tokens,
334	              completionTokens: event.completion_tokens,
335	              totalTokens: event.prompt_tokens + event.completion_tokens
336	            };
337	          }
338	          yield event;
339	        }
340	      }
341	
342	      await this.persistTrace({
343	        kind: Array.isArray(input) ? "stream_chat" : "stream_completion",
344	        traceId,
345	        request: Array.isArray(input)
346	          ? { messages: input, metadata: options.metadata }
347	          : { prompt: input, metadata: options.metadata },
348	        response: {
349	          content: streamedContent.join(""),
350	          usage: latestUsage,
351	          traceId,
352	          trace_id: traceId,
353	          cost: this.attachCost(latestUsage)
354	        }
355	      });
356	    } catch (error) {
357	      const normalizedError = normalizeUnknownError(error);
358	      await span?.fail(normalizedError);
359	      yield withTrace<StreamEvent>(
360	        {
361	          type: "error",
362	          error: {
363	            code: normalizedError.code,
364	            message: normalizedError.message
365	          }
366	        },
367	        traceId
368	      );
369	    } finally {
370	      await span?.[Symbol.asyncDispose]();
371	    }
372	  }
