    14	export class CompiledGraph<TState extends Record<string, unknown>> {
    15	  constructor(
    16	    private readonly config: {
    17	      initialState: TState;
    18	      nodes: Map<string, NodeFn<TState>>;
    19	      edges: Map<string, string>;
    20	      conditionalEdges: Map<string, RouteFn<TState>>;
    21	      interruptBefore: Set<string>;
    22	      entrypoint: string;
    23	    }
