    26	  async invoke(state?: Partial<TState>, options: InvokeGraphOptions<TState> = {}): Promise<TState> {
    27	    return await this.run({
    28	      checkpointStore: options.checkpointStore,
    29	      currentNode: this.config.entrypoint,
    30	      currentState: { ...this.config.initialState, ...(state ?? {}) } as TState,
    31	      executedSteps: 0,
    32	      maxSteps: options.maxSteps ?? 100
    33	    });
    34	  }
    35	
    36	  async resume(checkpointId: string, options: InvokeGraphOptions<TState> = {}): Promise<TState> {
