    43	      checkpointStore: store,
    44	      currentNode: checkpoint.node,
    45	      currentState: checkpoint.state,
    46	      executedSteps: checkpoint.steps,
    47	      maxSteps: options.maxSteps ?? 100,
    48	      skipInterruptFor: checkpoint.node
    49	    });
    50	  }
    51	
    52	  private async run(options: {
    53	    checkpointStore?: CheckpointStore<TState>;
    54	    currentNode: string;
    55	    currentState: TState;
    56	    executedSteps: number;
    57	    maxSteps: number;
    58	    skipInterruptFor?: string;
    59	  }): Promise<TState> {
    60	    let currentNode = options.currentNode;
    61	    let currentState = options.currentState;
    62	    let executedSteps = options.executedSteps;
    63	    let skipInterruptFor = options.skipInterruptFor;
    64	    const store = options.checkpointStore;
    65	
    66	    while (true) {
    67	      if (executedSteps >= options.maxSteps) {
    68	        throw new GraphMaxStepsError("Graph exceeded max steps", {
    69	          metadata: { node: currentNode, maxSteps: options.maxSteps }
    70	        });
    71	      }
