    81	          metadata: { checkpointId, node: currentNode }
    82	        });
    83	      }
    84	      skipInterruptFor = undefined;
    85	
    86	      const node = this.config.nodes.get(currentNode);
    87	      if (!node) {
    88	        throw new InternalError(`Unknown graph node: ${currentNode}`, { metadata: { node: currentNode } });
    89	      }
    90	
    91	      try {
    92	        currentState = await node(currentState);
    93	      } catch (error) {
    94	        if (error instanceof Error && "code" in error) {
    95	          throw error;
    96	        }
    97	        throw new InternalError(`Graph node '${currentNode}' failed`, {
    98	          metadata: { node: currentNode },
    99	          cause: error
   100	        });
   101	      }
   102	      executedSteps += 1;
   103	
   104	      const router = this.config.conditionalEdges.get(currentNode);
   105	      let nextNode: string | undefined;
   106	      if (router) {
   107	        try {
   108	          nextNode = await router(currentState);
   109	        } catch (error) {
   110	          throw new InternalError(`Conditional edge '${currentNode}' failed`, {
   111	            metadata: { node: currentNode },
   112	            cause: error
   113	          });
   114	        }
   115	      } else {
   116	        nextNode = this.config.edges.get(currentNode);
   117	      }
   118	
   119	      if (!nextNode || nextNode === END) {
   120	        return currentState;
   121	      }
   122	      if (!this.config.nodes.has(nextNode)) {
   123	        throw new InternalError(`Unknown graph node: ${nextNode}`, { metadata: { node: nextNode } });
   124	      }
   125	      currentNode = nextNode;
   126	    }
   127	  }
   128	
   129	  private async saveCheckpoint(
   130	    store: CheckpointStore<TState> | undefined,
   131	    checkpoint: GraphCheckpoint<TState>
   132	  ): Promise<string> {
   133	    if (!store) {
   134	      return checkpoint.id;
   135	    }
   136	    await store.save(checkpoint);
   137	    return checkpoint.id;
   138	  }
   139	}
