   141	export class StateGraph<TState extends Record<string, unknown>> {
   142	  private readonly nodes = new Map<string, NodeFn<TState>>();
   143	  private readonly edges = new Map<string, string>();
   144	  private readonly conditionalEdges = new Map<string, RouteFn<TState>>();
   145	  private readonly interruptBefore = new Set<string>();
   146	  private entrypoint?: string;
   147	
   148	  constructor(private readonly initialState: TState) {}
   149	
   150	  addNode(name: string, fn: NodeFn<TState>): this {
   151	    if (this.nodes.has(name)) {
   152	      throw new ValidationError(`Node already exists: ${name}`, { metadata: { node: name } });
   153	    }
   154	    this.nodes.set(name, fn);
   155	    return this;
   156	  }
   157	
   158	  addEdge(from: string, to: string): this {
   159	    this.edges.set(from, to);
   160	    return this;
   161	  }
   162	
   163	  addConditionalEdge(from: string, router: RouteFn<TState>): this {
   164	    this.conditionalEdges.set(from, router);
   165	    return this;
   166	  }
   167	
   168	  addInterrupt(node: string): this {
   169	    this.interruptBefore.add(node);
   170	    return this;
   171	  }
   172	
   173	  setEntryPoint(name: string): this {
   174	    this.entrypoint = name;
   175	    return this;
   176	  }
   177	
   178	  compile(): CompiledGraph<TState> {
   179	    if (!this.entrypoint) {
   180	      throw new ValidationError("Entrypoint not set");
   181	    }
   182	    if (!this.nodes.has(this.entrypoint)) {
   183	      throw new ValidationError(`Entry point node not found: ${this.entrypoint}`, {
   184	        metadata: { node: this.entrypoint }
   185	      });
   186	    }
   187	    return new CompiledGraph({
   188	      initialState: { ...this.initialState },
   189	      nodes: this.nodes,
   190	      edges: this.edges,
   191	      conditionalEdges: this.conditionalEdges,
   192	      interruptBefore: this.interruptBefore,
   193	      entrypoint: this.entrypoint
   194	    });
   195	  }
   196	}
