     1	import { LangFn } from "../client.js";
     2	import { ValidationError } from "../core/errors.js";
     3	import { Message } from "../core/types.js";
     4	
     5	type Summarizer = (payload: { existingSummary: string | undefined; messages: Message[] }) => Promise<string> | string;
     6	
     7	export class SummaryMemory {
     8	  private messages: Message[] = [];
     9	  private summary?: string;
    10	  readonly maxMessages: number;
    11	  private readonly summarizer?: Summarizer;
    12	  private readonly summaryPrompt: string;
    13	
    14	  constructor(
    15	    private readonly lang?: LangFn,
    16	    options: { maxMessages?: number; summaryPrompt?: string; summarizer?: Summarizer } = {}
    17	  ) {
    18	    this.maxMessages = options.maxMessages ?? 10;
    19	    if (this.maxMessages < 0) {
    20	      throw new ValidationError("SummaryMemory maxMessages must be non-negative", {
    21	        metadata: { maxMessages: this.maxMessages }
    22	      });
    23	    }
    24	    this.summaryPrompt =
    25	      options.summaryPrompt ??
    26	      "Summarize the following conversation history concisely, retaining all key information:";
    27	    this.summarizer = options.summarizer;
    28	  }
    29	
    30	  async add(message: Message): Promise<void> {
    31	    this.messages.push({ ...message });
    32	    await this.compactIfNeeded();
    33	  }
    34	
    35	  async extend(messages: Message[]): Promise<void> {
    36	    for (const message of messages) {
    37	      await this.add(message);
    38	    }
    39	  }
    40	
    41	  async get(): Promise<Message[]> {
    42	    const history: Message[] = [];
    43	    if (this.summary) {
    44	      history.push({ role: "system", content: `Previous conversation summary: ${this.summary}` });
    45	    }
    46	    history.push(...this.messages.map((message) => ({ ...message })));
    47	    return history;
    48	  }
    49	
    50	  getSummary(): string | undefined {
    51	    return this.summary;
    52	  }
    53	
    54	  async clear(): Promise<void> {
    55	    this.messages = [];
    56	    this.summary = undefined;
    57	  }
    58	
    59	  private async compactIfNeeded(): Promise<void> {
    60	    if (this.messages.length <= this.maxMessages) {
    61	      return;
    62	    }
    63	
    64	    const overflowCount = this.messages.length - this.maxMessages;
    65	    const toSummarize = this.messages.slice(0, overflowCount);
    66	    this.summary = await this.createSummary(toSummarize);
    67	    this.messages = this.messages.slice(overflowCount);
    68	  }
    69	
    70	  private async createSummary(messages: Message[]): Promise<string> {
    71	    if (this.summarizer) {
    72	      return await this.summarizer({ existingSummary: this.summary, messages });
    73	    }
    74	    if (!this.lang) {
    75	      return [this.summary, ...messages.map((message) => `${message.role}: ${message.content}`)]
    76	        .filter(Boolean)
    77	        .join("\n");
    78	    }
    79	
    80	    const prompt = [
    81	      this.summaryPrompt,
    82	      "",
    83	      `Existing Summary: ${this.summary ?? "None"}`,
    84	      "",
    85	      "New Messages:",
    86	      ...messages.map((message) => `${message.role}: ${message.content}`)
    87	    ].join("\n");
    88	    const response = await this.lang.complete(prompt);
    89	    return response.content;
    90	  }
    91	}

