 19	function parseSemver(version: string): [number, number, number] {
 20	  const parts = version.split(".");
 21	  if (parts.length !== 3 || parts.some((part) => !/^\d+$/.test(part))) {
 22	    throw new ValidationError("Prompt registry versions must be semantic versions", {
 23	      metadata: { version }
 24	    });
 25	  }
 26	  return [Number(parts[0]), Number(parts[1]), Number(parts[2])];
 27	}
 28	
 29	function promptSortKey(record: PromptRecord): [number, number, number, number] {
 30	  const [major, minor, patch] = parseSemver(record.version);
 31	  return [major, minor, patch, record.updatedAt];
 32	}
