 34	export class PromptRegistry {
 35	  private readonly tableName = "langfn_prompts";
 36	
 37	  constructor(private readonly db: Adapter) {}
 38	
 39	  async save(
 40	    name: string,
 41	    prompt: PromptTemplate,
 42	    options: {
 43	      version: string;
 44	      description?: string;
 45	      tags?: string[];
 46	      metadata?: Record<string, unknown>;
 47	    }
 48	  ): Promise<PromptTemplate> {
 49	    parseSemver(options.version);
 50	    const now = Date.now();
 51	    const record: PromptRecord = {
 52	      id: `${name}:${options.version}`,
 53	      name,
 54	      version: options.version,
 55	      template: prompt.template,
 56	      variables: [...prompt.requiredVariables],
 57	      description: options.description ?? prompt.description,
 58	      tags: [...(options.tags ?? prompt.tags)],
 59	      metadata: { ...(options.metadata ?? prompt.metadata) },
 60	      createdAt: now,
 61	      updatedAt: now
 62	    };
 63	
 64	    await this.db.upsert({
 65	      model: this.tableName,
 66	      where: [{ field: "id", operator: "eq", value: record.id }] as WhereClause[],
 67	      create: record,
 68	      update: record
 69	    });
 70	
 71	    return toPromptTemplate(record);
 72	  }
 73	
 74	  async load(name: string, options: { version?: string } = {}): Promise<PromptTemplate> {
 75	    const version = options.version ?? "latest";
 76	    const record =
 77	      version === "latest" ? await this.loadLatest(name) : await this.loadExact(name, version);
 78	
 79	    if (!record) {
 80	      throw new LangFnError(`Prompt not found: ${name}@${version}`, {
 81	        code: "NOT_FOUND",
 82	        metadata: { name, version }
 83	      });
 84	    }
 85	
 86	    return toPromptTemplate(record);
 87	  }
 88	
 89	  async list(name?: string): Promise<PromptTemplate[]> {
 90	    const where = name
 91	      ? ([{ field: "name", operator: "eq", value: name }] as WhereClause[])
 92	      : undefined;
 93	    const records = await this.db.findMany<PromptRecord>({
 94	      model: this.tableName,
 95	      where
 96	    });
 97	
 98	    return [...records]
 99	      .filter((record) => {
100	        try {
101	          parseSemver(record.version);
102	          return true;
103	        } catch {
104	          return false;
105	        }
106	      })
107	      .sort((left, right) => comparePromptRecords(right, left))
108	      .map(toPromptTemplate);
109	  }
110	
111	  private async loadExact(name: string, version: string): Promise<PromptRecord | null> {
112	    parseSemver(version);
113	    return await this.db.findOne<PromptRecord>({
114	      model: this.tableName,
115	      where: [{ field: "id", operator: "eq", value: `${name}:${version}` }] as WhereClause[]
116	    });
117	  }
118	
119	  private async loadLatest(name: string): Promise<PromptRecord | null> {
120	    const records = await this.db.findMany<PromptRecord>({
121	      model: this.tableName,
122	      where: [{ field: "name", operator: "eq", value: name }] as WhereClause[]
123	    });
124	    const valid = records.filter((record) => {
125	      try {
126	        parseSemver(record.version);
127	        return true;
128	      } catch {
129	        return false;
130	      }
131	    });
132	    if (!valid.length) {
133	      return null;
134	    }
135	    valid.sort((left, right) => comparePromptRecords(right, left));
136	    return valid[0];
137	  }
138	}
139	
140	function comparePromptRecords(left: PromptRecord, right: PromptRecord): number {
141	  const leftKey = promptSortKey(left);
142	  const rightKey = promptSortKey(right);
143	  for (let index = 0; index < leftKey.length; index += 1) {
144	    if (leftKey[index] > rightKey[index]) return 1;
145	    if (leftKey[index] < rightKey[index]) return -1;
146	  }
147	  return 0;
148	}
