 47	    this.backendType = options.mode ?? "reference";
 48	    this.pageSize = Math.max(1, options.pageSize ?? 64);
 49	    this.maxScan = Math.max(this.pageSize, options.maxScan ?? 512);
 50	    this.indexedSearch = options.indexedSearch;
 51	  }
