 53	  async addDocuments(documents: Document[]): Promise<void> {
 54	    const texts = documents.map((document) => document.content);
 55	    const vectors = await this.embeddings.embedDocuments(texts);
 56	    const records: DocumentRecord[] = documents.map((document, index) => ({
 57	      id: `doc_${index}_${Date.now()}`,
 58	      content: document.content,
 59	      embedding: vectors[index]!,
 60	      metadata: { ...document.metadata },
 61	      namespace: this.namespace,
 62	      createdAt: Date.now()
