 72	    const queryEmbedding = await this.embeddings.embedQuery(query);
 73	    const records = this.indexedSearch
 74	      ? await this.indexedSearch({
 75	          query,
 76	          k,
 77	          filter: options.filter,
 78	          namespace: this.namespace,
 79	          queryEmbedding
 80	        })
 81	      : await this.referenceSearch(queryEmbedding, options, k);
