 92	  private async referenceSearch(
 93	    queryEmbedding: number[],
 94	    options: RetrievalOptions,
 95	    k: number
 96	  ): Promise<DocumentRecord[]> {
 97	    if (this.backendType === "production") {
 98	      throw new NonProductionBackendError("Production retrieval requires adapter-native indexed search or memoryfn", {
 99	        metadata: { backend: "db-vector-store" }
100	      });
101	    }
102	
103	    const where: WhereClause[] = [{ field: "namespace", operator: "eq", value: this.namespace }];
104	    const scored: DocumentRecord[] = [];
105	    let offset = 0;
106	
107	    while (offset < this.maxScan) {
108	      const limit = Math.min(this.pageSize, this.maxScan - offset);
109	      const records = await this.db.findMany<DocumentRecord>({
110	        model: this.tableName,
111	        where,
112	        limit,
113	        offset
114	      });
115	      if (!records.length) {
116	        break;
117	      }
118	
119	      records.forEach((record, index) => {
120	        if (!matchesRetrievalFilter(record.metadata ?? {}, options.filter)) {
121	          return;
122	        }
123	        scored.push({
124	          ...record,
125	          score: cosineSimilarity(queryEmbedding, record.embedding),
126	          createdAt: record.createdAt ?? offset + index
127	        });
128	      });
