130	      offset += records.length;
131	      if (records.length < limit) {
132	        break;
133	      }
134	    }
135	
136	    return scored
137	      .sort((left, right) => (right.score ?? 0) - (left.score ?? 0) || left.createdAt - right.createdAt)
