    30	def create_rate_limit_middleware(
    31	    *,
    32	    route_id: str,
    33	    config: Optional[LangFnRateLimitConfig] = None,
    34	    get_tenant_context: Optional[Callable[[Request, Optional[AuthSession]], CanonicalTenantContext]] = None,
    35	):
    36	    if config is None or config.provider is None:
    37	        async def passthrough(_request: Request, _context: LangFnRouteContext, next_handler):
    38	            return await next_handler(_request, _context)
    39	
    40	        return passthrough
    41	
    42	    resolver = get_tenant_context or extract_tenant_context
    43	
    44	    async def middleware(request: Request, context: LangFnRouteContext, next_handler):
    45	        tenant_context = resolver(request, context.auth)
    46	        context.tenant_context = tenant_context
    47	        session = context.auth
    48	        key = ":".join(
    49	            [
    50	                tenant_context.tenant_id or "anonymous",
    51	                tenant_context.user_id or (session.subject.actor_id if session is not None else "anonymous"),
    52	                route_id,
    53	            ]
    54	        )
    55	        decision = await config.provider.consume(
    56	            {
    57	                "key": key,
    58	                "route_id": route_id,
    59	                "tenant_context": tenant_context,
    60	                "request": request,
    61	                "session": session,
    62	            }
    63	        )
    64	        context.rate_limit = {
    65	            "allowed": decision.allowed,
    66	            "key": decision.key,
    67	            "remaining": decision.remaining,
    68	            "retry_after_ms": decision.retry_after_ms,
    69	        }
    70	        if decision.allowed:
