 19	def create_auth_middleware(config: Optional[LangFnAuthConfig] = None):
 20	    if config is None or (config.provider is None and config.validate_bearer_token is None):
 21	        async def passthrough(_request: Request, _context: LangFnRouteContext, next_handler):
 22	            return await next_handler(_request, _context)
 23	
 24	        return passthrough
