 26	    async def middleware(request: Request, context: LangFnRouteContext, next_handler):
 27	        try:
 28	            session = await _authenticate(request, config)
 29	            validated = validate_auth_session(session) if isinstance(session, dict) else session
 30	        except AuthValidationError:
 31	            session = None
 32	            validated = None
 33	        except Exception:
 34	            raise
 35	
 36	        if validated is None:
 37	            return Response(
 38	                status=401,
 39	                headers={"content-type": "application/json"},
 40	                body=error_envelope("AUTH_REQUIRED", "Authentication required"),
 41	            )
 42	
 43	        context.auth = validated
 44	        return await next_handler(request, context)
 45	
