 49	async def _authenticate(request: Request, config: LangFnAuthConfig) -> Optional[AuthSession]:
 50	    if config.provider is not None:
 51	        return await config.provider.authenticate(request)
 52	
 53	    token = extract_bearer_token(request, header_name=config.header_name)
 54	    if token is None or config.validate_bearer_token is None:
 55	        return None
 56	    result = config.validate_bearer_token(token, request)
 57	    if hasattr(result, "__await__"):
 58	        return await result
 59	    return result
