 62	def extract_bearer_token(request: Request, *, header_name: str = "authorization") -> Optional[str]:
 63	    for key, value in request.headers.items():
 64	        if key.lower() != header_name.lower():
 65	            continue
 66	        parts = str(value).strip().split(" ", 1)
 67	        if len(parts) == 2 and parts[0].lower() == "bearer" and parts[1].strip():
 68	            return parts[1].strip()
 69	    return None
