 81	export function toHttpErrorPayload(error: unknown): {
 82	  status: number;
 83	  code: string;
 84	  message: string;
 85	  details?: Record<string, unknown>;
 86	} {
 87	  if (error instanceof ValidationError) {
 88	    return { status: 400, code: "VALIDATION_ERROR", message: error.message, details: error.metadata };
 89	  }
 90	  if (error instanceof LangFnError) {
 91	    return { status: statusForLangFnCode(error.code), code: error.code, message: error.message, details: error.metadata };
 92	  }
 93	  return { status: 500, code: "INTERNAL_ERROR", message: error instanceof Error ? error.message : String(error) };
