118	export function parseMessages(input: Message[]): Message[] {
119	  if (!Array.isArray(input) || input.length === 0) {
120	    throw new ValidationError("messages must be a non-empty array");
121	  }
122	
123	  return input.map((message, index) => {
124	    if (!isRecord(message)) {
125	      throw new ValidationError("message must be an object", { metadata: { index } });
126	    }
127	    const role = asNonEmptyString(message.role, `messages[${index}].role`);
128	    if (!["system", "user", "assistant", "tool"].includes(role)) {
129	      throw new ValidationError("message role must be one of system, user, assistant, or tool", {
130	        metadata: { index, role }
131	      });
132	    }
133	
134	    return {
135	      role: role as Message["role"],
136	      content: asNonEmptyString(message.content, `messages[${index}].content`),
137	      ...(typeof message.name === "string" && message.name.length > 0 ? { name: message.name } : {}),
138	      ...(typeof message.tool_call_id === "string" && message.tool_call_id.length > 0
139	        ? { tool_call_id: message.tool_call_id }
140	        : {})
141	    };
142	  });
143	}
