    98	function buildSurfaceManifest(
    99	  surfaces: readonly ResolvedPageSurface[],
   100	  pages: Partial<Record<ResolvedPageSurface['surface'], string>>
   101	): Record<string, unknown> {
   102	  const manifest: Record<string, unknown> = {};
   103	
   104	  for (const surface of surfaces) {
   105	    const outputPath = pages[surface.surface];
   106	    if (!outputPath) {
   107	      continue;
   108	    }
   109	
   110	    if (surface.surface === 'popup') {
   111	      manifest.action = {
   112	        default_popup: outputPath,
   113	        ...(surface.title ? { default_title: surface.title } : {}),
   114	      };
   115	    } else if (surface.surface === 'options') {
   120	        bundle: OutputBundle
   121	      ): Promise<void> {
   122	        if (!resolvedExtension) {
   123	          return;
   124	        }
   125	
   126	        await emitTargetOutputs({
   127	          bundle,
   128	          mode: 'build',
   129	          outDir: resolveOutDir(
   130	            viteConfig?.root ?? process.cwd(),
   131	            outputOptions.dir ?? viteConfig?.build.outDir ?? 'dist'
   132	          ),
   133	          resolvedConfig: resolvedExtension.resolved,
   134	        });
   135	      },
   136	    },
   137	  ];
