   140	function createRollupInputs(
   141	  resolvedConfig: ResolvedExtensionConfig
   142	): Record<string, string> {
   143	  const inputs: Record<string, string> = {};
   144	
   145	  for (const surface of resolvedConfig.surfaces) {
   146	    const key = normalizePageInputKey(surface.outputPath);
   147	    if (inputs[key]) {
   148	      throw new ExtfnError(
   149	        'E_MANIFEST_COLLISION',
   150	        `Duplicate page output path: ${surface.outputPath}`,
   151	        {
   152	          details: {
   153	            outputPath: surface.outputPath,
   154	            surface: surface.surface,
   155	          },
   156	        }
   157	      );
   158	    }
   159	    inputs[key] = surface.resolvedEntry;
   160	  }
   161	
   162	  inputs.background = resolvedConfig.background.resolvedServiceWorker;
   163	
   164	  for (const contentScript of resolvedConfig.contentScripts) {
   165	    const key = `content/${contentScript.id}`;
   166	    if (inputs[key]) {
   167	      throw new ExtfnError(
   168	        'E_MANIFEST_COLLISION',
   169	        `Duplicate content output path: ${key}.js`,
   170	        {
   171	          details: {
   172	            contentScriptId: contentScript.id,
   173	          },
   174	        }
   175	      );
   176	    }
   177	    inputs[key] = contentScript.resolvedEntry;
   178	  }
   179	
   180	  return inputs;
   181	}
