   188	async function emitTargetOutputs(input: {
   189	  resolvedConfig: ResolvedExtensionConfig;
   190	  outDir: string;
   191	  mode: ExtfnOutputMode;
   192	  bundle?: OutputBundle;
   193	}): Promise<void> {
   194	  const targetDirectories = await ensureTargetOutputDirectories(
   195	    input.outDir,
   196	    input.resolvedConfig.targets,
   197	    input.mode
   198	  );
   199	  const buildOutputs = createTargetBuildOutputs(input.resolvedConfig);
   200	
   201	  for (const target of input.resolvedConfig.targets) {
   202	    const outputDirectory = targetDirectories[target];
   203	
   204	    if (input.bundle) {
   205	      await copyBundleToTarget(outputDirectory, input.bundle);
   206	    }
   207	
   208	    await copyContentCss(input.resolvedConfig, outputDirectory);
   209	
   210	    const manifest = buildManifest(input.resolvedConfig, target, buildOutputs);
   211	    await writeTargetFile(
   212	      outputDirectory,
   213	      'manifest.json',
   214	      `${JSON.stringify(manifest, null, 2)}\n`
   215	    );
   216	  }
   217	}
   218	
   219	async function copyBundleToTarget(
   220	  outputDirectory: string,
   221	  bundle: OutputBundle
   222	): Promise<void> {
   223	  const entries = (Object.values(bundle) as Array<OutputBundle[string]>).sort(
   224	    (left, right) => left.fileName.localeCompare(right.fileName)
   225	  );
   226	
   227	  for (const entry of entries) {
   228	    if (entry.type === 'chunk') {
   229	      await writeTargetFile(outputDirectory, entry.fileName, entry.code);
   230	      continue;
   231	    }
   232	
   233	    const contents =
   234	      typeof entry.source === 'string'
   235	        ? entry.source
   236	        : new Uint8Array(entry.source);
   237	    await writeTargetFile(outputDirectory, entry.fileName, contents);
   238	  }
   239	}
   240	
   241	async function copyContentCss(
   242	  resolvedConfig: ResolvedExtensionConfig,
   243	  outputDirectory: string
   244	): Promise<void> {
   245	  for (const contentScript of resolvedConfig.contentScripts) {
   246	    for (const cssPath of contentScript.resolvedCss) {
   247	      const targetPath = path.posix.join(
   248	        'content',
   249	        contentScript.id,
   250	        path.basename(cssPath)
   251	      );
   252	      await writeTargetFile(outputDirectory, targetPath, await fs.readFile(cssPath));
   253	    }
   254	  }
   255	}
