    18	  // Called on URL change or event
    19	  getEligibleMessages(
    20	    triggerType: CampaignTrigger['type'],
    21	    triggerContext: string, // URL or Event Name
    22	    user: UserIdentity | null
    23	  ): Campaign[] {
    24	    if (!user) return []; // Messaging usually requires identity
    25	
    26	    const eligible: Campaign[] = [];
    27	
    28	    for (const campaign of this.campaigns.values()) {
    29	      if (!campaign.enabled) continue;
    30	
    31	      // 1. Check Triggers
    32	      const matchesTrigger = campaign.triggers.some(t => {
    33	        if (t.type !== triggerType) return false;
    34	        if (t.type === 'url_match' || t.type === 'event') {
    35	          // Simple string match or regex if pattern provided
    36	          // Assuming simple glob/substring for now if it's URL
    37	          if (!t.pattern) return true;
    38	          // Simple "includes" or "exact" for now. 
    39	          // For URL, usually glob. 
    40	          return triggerContext.includes(t.pattern);
    41	        }
    42	        return false;
    43	      });
    44	
    45	      if (!matchesTrigger) continue;
    46	
    47	      // 2. Check Audience (Segments)
    48	      if (campaign.segmentId) {
    49	        if (!this.segments.evaluate(campaign.segmentId, user.traits)) {
    50	          continue;
    51	        }
    52	      }
    53	
    54	      // 3. Check Frequency Caps (Simple global cap for now)
    55	      const campaignDeliveries = this.deliveries.get(campaign.id) || [];
    56	      const shownCount = campaignDeliveries.filter(d => d.status === 'shown').length;
    57	      if (campaign.caps?.global && shownCount >= campaign.caps.global) {
    58	        continue;
    59	      }
