     2	import { SegmentEvaluator } from './segments';
     3	import { getBucket } from '../utils/hash';
     4	
     5	export class FlagEvaluator {
     6	  private flags: Map<string, FlagConfig> = new Map();
     7	  private segments: SegmentEvaluator;
     8	
     9	  constructor(initialFlags: FlagConfig[] = [], segmentEvaluator: SegmentEvaluator) {
    10	    this.flags = new Map(initialFlags.map(f => [f.key, f]));
    11	    this.segments = segmentEvaluator;
    12	  }
    13	
    14	  setFlags(flags: FlagConfig[]) {
    15	    this.flags.clear();
    16	    flags.forEach(flag => this.flags.set(flag.key, flag));
    17	  }
    18	
    19	  getFlag(key: string, defaultValue: FlagValue, user?: UserIdentity | null): FlagValue {
    20	    const flag = this.flags.get(key);
    21	
    22	    if (!flag) {
    23	      return defaultValue;
    24	    }
    25	
    26	    if (!flag.enabled) {
    27	      return defaultValue;
    28	    }
    29	
    30	    // Evaluate rules in order
    31	    for (const rule of flag.rules) {
    32	      // 1. Check constraints (Segment & Inline)
    33	      if (!this.matchesConstraints(rule, user)) {
    34	        continue;
    35	      }
    36	
    37	      // 2. Check Rollout
    38	      if (rule.rolloutPercentage !== undefined && rule.rolloutPercentage !== null) {
    39	        // If 100%, skip hash check
    40	        if (rule.rolloutPercentage < 100) {
    41	           if (!user) continue; // Anon users fail partial rollouts? Or fall through.
    42	           const bucket = getBucket(flag.key, user.id);
    43	           if (bucket >= rule.rolloutPercentage) {
    44	             continue; // User is in the upper bucket, so this rule doesn't apply to them.
    45	           }
    46	        }
    47	      }
    48	
    49	      // 3. Return Variation
    50	      if (rule.variationId) {
    51	        const variation = flag.variations.find(v => v.id === rule.variationId);
    52	        if (variation) return variation.value;
    53	      }
    54	      
    55	      // If rule matches but no variation ID, skip it or return default.
    56	      continue;
    57	    }
    58	
    59	    // Fallback
    60	    if (flag.defaultVariationId) {
    61	      const variation = flag.variations.find(v => v.id === flag.defaultVariationId);
    62	      if (variation) return variation.value;
    63	    }
    64	
    65	    return flag.defaultValue;
    66	  }
    67	
    68	  private matchesConstraints(rule: FlagRule, user?: UserIdentity | null): boolean {
    69	    if (!user) {
    70	      // Anonymous matching: allowed only if no constraints defined
    71	      if (rule.segmentId || (rule.constraints && rule.constraints.length > 0)) {
    72	        return false;
    73	      }
    74	      return true;
    75	    }
    76	
    77	    // Check Segment
    78	    if (rule.segmentId) {
    79	      const matchesSegment = this.segments.evaluate(rule.segmentId, user.traits);
    80	      if (!matchesSegment) return false;
    81	    }
    82	
    83	    // Check Inline Constraints
    84	    if (rule.constraints && rule.constraints.length > 0) {
    85	      const matchesConstraints = rule.constraints.every(c => 
    86	        this.segments.matchesRule(c, user.traits)
    87	      );
    88	      if (!matchesConstraints) return false;
    89	    }
    90	
    91	    return true;
    92	  }
