  2	import { Memory, MemoryRelationship, SearchMemoryInput } from '../../core/types';
  3	import { memories, memoryRelationships } from './schema';
  4	import { eq, and, sql, desc, inArray } from 'drizzle-orm';
  5	import { PostgresJsDatabase } from 'drizzle-orm/postgres-js';
  6	
  7	// We assume the DB passed is compatible with PostgresJsDatabase schema
  8	export class PostgresAdapter implements StorageAdapter {
  9	  private db: PostgresJsDatabase<any>;
 10	
 11	  constructor(db: PostgresJsDatabase<any>) {
 12	    this.db = db;
 13	  }
 14	
 15	  async insertMemories(memoryInputs: Partial<Memory>[]): Promise<Memory[]> {
 16	    if (memoryInputs.length === 0) return [];
 17	
 18	    const now = new Date();
 19	    
 20	    // Map domain model to schema
 21	    const values = memoryInputs.map(m => ({
 22	      // id is autogenerated if not present, but we prefer letting DB generate it or using what's passed
 23	      ...(m.id ? { id: m.id } : {}),
 24	      tenantId: m.tenantId || 'default',
 25	      containerTags: m.containerTags || [],
 26	      type: m.type || 'conversational',
 27	      content: m.content || '',
 28	      embedding: m.embedding || null,
 29	      metadata: m.metadata || {},
 30	      isLatest: m.isLatest ?? true,
 31	      createdAt: m.createdAt ? new Date(m.createdAt) : now,
 32	      updatedAt: m.updatedAt ? new Date(m.updatedAt) : now,
 33	    }));
 34	
 35	    const result = await this.db.insert(memories)
 36	      .values(values)
 37	      .returning();
 38	
 39	    return result.map(this.mapToDomain);
 40	  }
 41	
 42	  async insertRelationships(relationships: Partial<MemoryRelationship>[]): Promise<MemoryRelationship[]> {
 43	    if (relationships.length === 0) return [];
 44	
 45	    const now = new Date();
 46	    const values = relationships.map(r => ({
 47	      fromId: r.fromId!,
 48	      toId: r.toId!,
 49	      type: r.type || 'extends',
 50	      confidence: r.confidence || 1.0,
 51	      reasoning: r.reasoning,
 52	      createdAt: r.createdAt ? new Date(r.createdAt) : now,
 53	    }));
 54	
 55	    const result = await this.db.insert(memoryRelationships)
 56	      .values(values)
 57	      .returning();
 58	
 59	    return result.map(r => ({
 60	      id: r.id,
 61	      fromId: r.fromId,
 62	      toId: r.toId,
 63	      type: r.type as any,
 64	      confidence: r.confidence,
 65	      reasoning: r.reasoning || undefined,
 66	      createdAt: r.createdAt.getTime(),
 67	    }));
 68	  }
 69	
 70	  async searchVectors(params: {
 71	    embedding: number[];
 72	    containerTags: string[];
 73	    filters?: Record<string, any>;
 74	    topK: number;
 75	    threshold?: number;
 76	  }): Promise<Memory[]> {
 77	    const { embedding, containerTags, topK, threshold } = params;
 78	
 79	    // pgvector cosine similarity operator is <=>
 80	    // We want to sort by distance ascending (closest first)
 81	    // distance = 1 - similarity
 82	    // To filter by threshold (similarity), distance should be <= (1 - threshold)
 83	    
 84	    const similarity = sql<number>`1 - (${memories.embedding} <=> ${JSON.stringify(embedding)}::vector)`;
 85	    
 86	    let query = this.db.select({
 87	      memory: memories,
 88	      similarity: similarity
 89	    })
 90	    .from(memories);
 91	
 92	    // Build Where Clauses
 93	    const conditions = [];
 94	
 95	    // Filter by container tags (overlap)
 96	    // We want memory to have AT LEAST ONE of the requested tags? 
 97	    // Or MUST contain ALL? Usually scoping means "must match context".
 98	    // Spec says: "Container Tags scope memories to specific contexts"
 99	    // Usually this means the memory must belong to at least one of the contexts in the query, 
100	    // OR matching specific tag sets.
101	    // Simple implementation: Memory must have one of the tags in the query list.
102	    // Postgres array overlap: &&
103	    if (containerTags && containerTags.length > 0) {
104	      conditions.push(sql`${memories.containerTags} && ${containerTags}`);
105	    }
106	
107	    if (threshold) {
108	        conditions.push(sql`(${memories.embedding} <=> ${JSON.stringify(embedding)}::vector) <= ${1 - threshold}`);
109	    }
110	
111	    if (params.filters) {
112	        // Simple metadata exact match support
113	        for (const [key, value] of Object.entries(params.filters)) {
114	            // JSONB containment @>
115	            conditions.push(sql`${memories.metadata} @> ${JSON.stringify({ [key]: value })}`);
116	        }
117	    }
118	
119	    if (conditions.length > 0) {
120	        query = query.where(and(...conditions)) as any;
121	    }
122	
123	    const results = await query
124	        .orderBy(sql`${memories.embedding} <=> ${JSON.stringify(embedding)}::vector ASC`)
125	        .limit(topK);
126	
127	    return results.map(r => this.mapToDomain(r.memory));
128	  }
129	
130	  private mapToDomain(row: typeof memories.$inferSelect): Memory {
131	    return {
132	      id: row.id,
133	      tenantId: row.tenantId,
134	      containerTags: row.containerTags,
135	      type: row.type as any,
136	      content: row.content,
137	      embedding: row.embedding,
138	      metadata: row.metadata as Record<string, any>,
139	      isLatest: row.isLatest,
140	      createdAt: row.createdAt.getTime(),
141	      updatedAt: row.updatedAt.getTime(),
142	    };
143	  }
144	}
