  1	/**
  2	 * Validation utilities for log events
  3	 */
  4	
  5	import type { LogEvent, SerializationResult } from "./types.js";
  6	import { MAX_EVENT_SIZE, MAX_TAGS } from "./types.js";
  7	
  8	/**
  9	 * Checks if a value is serializable to JSON
 10	 */
 11	export function isSerializable(value: unknown): boolean {
 12	  if (value === null || value === undefined) {
 13	    return true;
 14	  }
 15	
 16	  const type = typeof value;
 17	
 18	  if (type === "function" || type === "symbol" || type === "bigint") {
 19	    return false;
 20	  }
 21	
 22	  if (type === "object") {
 23	    // Check for circular references would be expensive
 24	    // We'll rely on JSON.stringify catching those
 25	    return true;
 26	  }
 27	
 28	  return true;
 29	}
 30	
 31	/**
 32	 * Replaces non-serializable values with a placeholder
 33	 */
 34	export function sanitizeValue(value: unknown): unknown {
 35	  if (value === undefined) {
 36	    return undefined; // Will be dropped by Object.entries filter
 37	  }
 38	
 39	  if (value === null) {
 40	    return null;
 41	  }
 42	
 43	  const type = typeof value;
 44	
 45	  if (type === "function" || type === "symbol" || type === "bigint") {
 46	    return "[unserializable]";
 47	  }
 48	
 49	  if (type === "object") {
 50	    if (Array.isArray(value)) {
 51	      return value.map(sanitizeValue);
 52	    }
 53	
 54	    if (value instanceof Date) {
 55	      return value.toISOString();
 56	    }
 57	
 58	    if (value instanceof Error) {
 59	      return {
 60	        name: value.name,
 61	        message: value.message,
 62	        stack: value.stack,
 63	      };
 64	    }
 65	
 66	    // Plain object - sanitize recursively
 67	    const sanitized: Record<string, unknown> = {};
 68	    for (const [key, val] of Object.entries(value)) {
 69	      const cleaned = sanitizeValue(val);
 70	      if (cleaned !== undefined) {
 71	        sanitized[key] = cleaned;
 72	      }
 73	    }
 74	    return sanitized;
 75	  }
 76	
 77	  return value;
 78	}
 79	
 80	/**
 81	 * Validates and serializes a log event, enforcing size limits
 82	 */
 83	export function validateAndSerialize(event: LogEvent): SerializationResult {
 84	  // Sanitize the event
 85	  const sanitized: LogEvent = {
 86	    ...event,
 87	    ctx: event.ctx
 88	      ? (sanitizeValue(event.ctx) as Record<string, unknown>)
 89	      : undefined,
 90	    tags: event.tags?.slice(0, MAX_TAGS),
 91	  };
 92	
 93	  // Remove undefined fields
 94	  const cleaned: Partial<LogEvent> = {};
 95	  for (const [key, value] of Object.entries(sanitized)) {
 96	    if (value !== undefined) {
 97	      cleaned[key as keyof LogEvent] = value as never;
 98	    }
 99	  }
100	
101	  let finalEvent = cleaned as LogEvent;
102	  let truncated = false;
103	
104	  // Check size
105	  let serialized = JSON.stringify(finalEvent);
106	  if (serialized.length > MAX_EVENT_SIZE) {
107	    // Truncate context to fit
108	    truncated = true;
109	    const overhead = serialized.length - MAX_EVENT_SIZE;
110	    const ctxString = JSON.stringify(finalEvent.ctx || {});
111	
112	    if (ctxString.length > overhead + 100) {
113	      // Truncate context
114	      const truncatedCtx = ctxString.slice(
115	        0,
116	        Math.max(0, ctxString.length - overhead - 100)
117	      );
118	      finalEvent = {
119	        ...finalEvent,
120	        ctx: {
121	          ...finalEvent.ctx,
122	          _truncated: true,
123	          _originalSize: ctxString.length,
124	        },
125	      };
126	
127	      // Try to keep some context
128	      try {
129	        const parsed = JSON.parse(truncatedCtx + "}");
130	        finalEvent.ctx = { ...parsed, _truncated: true };
131	      } catch {
132	        // If parsing fails, just note truncation
133	        finalEvent.ctx = { _truncated: true, _reason: "size_limit" };
134	      }
135	    } else {
136	      // Even without context we're over, drop it entirely
137	      finalEvent.ctx = { _truncated: true, _reason: "size_limit" };
138	    }
139	  }
140	
141	  return { event: finalEvent, truncated };
142	}
143	
144	/**
145	 * Validates a log event schema
146	 */
147	export function isValidLogEvent(event: unknown): event is LogEvent {
148	  if (!event || typeof event !== "object") {
149	    return false;
150	  }
151	
152	  const e = event as Partial<LogEvent>;
153	
154	  // Required fields
155	  if (!e.ts || typeof e.ts !== "string") return false;
156	  if (!e.level || typeof e.level !== "string") return false;
157	  if (!e.msg || typeof e.msg !== "string") return false;
158	  if (!e.name || typeof e.name !== "string") return false;
159	  if (!e.version || typeof e.version !== "string") return false;
160	
161	  return true;
162	}
  1	/**
  2	 * HTTP sink for batched log transport
  3	 */
  4	
  5	import type { LogEvent, Sink } from "../types.js";
  6	
  7	/**
  8	 * HTTP sink options
  9	 */
 10	export interface HttpSinkOptions {
 11	  /** Target URL for log ingestion */
 12	  url: string;
 13	
 14	  /** Batch size before flushing (default: 50) */
 15	  batch?: number;
 16	
 17	  /** Flush interval in milliseconds (default: 1000) */
 18	  flushIntervalMs?: number;
 19	
 20	  /** Request timeout in milliseconds (default: 3000) */
 21	  timeoutMs?: number;
 22	
 23	  /** Additional headers */
 24	  headers?: Record<string, string>;
 25	
 26	  /** Authentication */
 27	  auth?: {
 28	    token?: string;
 29	    secretHeader?: string;
 30	  };
 31	
 32	  /** Retry configuration */
 33	  retry?: {
 34	    attempts?: number;
 35	    backoffMs?: number;
 36	  };
 37	
 38	  /** Offline buffer strategy */
 39	  offlineBuffer?: "memory" | "indexeddb";
 40	
 41	  /** Maximum queue size (default: 5000) */
 42	  maxQueue?: number;
 43	}
 44	
 45	/**
 46	 * Create an HTTP sink
 47	 */
 48	export function sinkHttp(options: HttpSinkOptions): Sink {
 49	  const {
 50	    url,
 51	    batch: batchSize = 50,
 52	    flushIntervalMs = 1000,
 53	    timeoutMs = 3000,
 54	    headers = {},
 55	    auth,
 56	    retry = {},
 57	    maxQueue = 5000,
 58	  } = options;
 59	
 60	  const { attempts = 5, backoffMs = 200 } = retry;
 61	
 62	  let buffer: LogEvent[] = [];
 63	  let flushTimer: ReturnType<typeof setTimeout> | null = null;
 64	  let flushing = false;
 65	
 66	  /**
 67	   * Send events to the HTTP endpoint with retry
 68	   */
 69	  async function sendBatch(events: LogEvent[]): Promise<void> {
 70	    const requestHeaders: Record<string, string> = {
 71	      "Content-Type": "application/json",
 72	      ...headers,
 73	    };
 74	
 75	    if (auth?.token) {
 76	      requestHeaders["Authorization"] = `Bearer ${auth.token}`;
 77	    }
 78	    if (auth?.secretHeader) {
 79	      requestHeaders[auth.secretHeader] = auth.token || "";
 80	    }
 81	
 82	    const controller = new AbortController();
 83	    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
 84	
 85	    let lastError: Error | null = null;
 86	
 87	    for (let attempt = 0; attempt < attempts; attempt++) {
 88	      try {
 89	        const response = await fetch(url, {
 90	          method: "POST",
 91	          headers: requestHeaders,
 92	          body: JSON.stringify({ events }),
 93	          signal: controller.signal,
 94	        });
 95	
 96	        clearTimeout(timeoutId);
 97	
 98	        if (response.ok) {
 99	          return; // Success
100	        }
101	
102	        // Don't retry on client errors
103	        if (response.status >= 400 && response.status < 500) {
104	          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
105	        }
106	
107	        // Retry on server errors
108	        lastError = new Error(
109	          `HTTP ${response.status}: ${response.statusText}`
110	        );
111	      } catch (error) {
112	        clearTimeout(timeoutId);
113	        lastError = error as Error;
114	
115	        // Don't retry on abort
116	        if (lastError.name === "AbortError") {
117	          throw lastError;
118	        }
119	      }
120	
121	      // Exponential backoff with jitter
122	      if (attempt < attempts - 1) {
123	        const delay = backoffMs * Math.pow(2, attempt) + Math.random() * 100;
124	        await new Promise((resolve) => setTimeout(resolve, delay));
125	      }
126	    }
127	
128	    throw lastError || new Error("Unknown error");
129	  }
130	
131	  /**
132	   * Flush buffered events
133	   */
134	  async function flushBuffer(): Promise<void> {
135	    if (flushing || buffer.length === 0) {
136	      return;
137	    }
138	
139	    flushing = true;
140	    const toSend = buffer.splice(0, buffer.length);
141	
142	    try {
143	      await sendBatch(toSend);
144	    } catch (error) {
145	      // On error, put events back at the front (up to maxQueue)
146	      const putBack = toSend.slice(0, Math.max(0, maxQueue - buffer.length));
147	      buffer.unshift(...putBack);
148	
149	      // Log error internally (without recursion)
150	      console.error("[logfn http-sink error]", error);
151	    } finally {
152	      flushing = false;
153	    }
154	  }
155	
156	  /**
157	   * Schedule a flush
158	   */
159	  function scheduleFlush(): void {
160	    if (flushTimer) {
161	      return;
162	    }
163	
164	    flushTimer = setTimeout(() => {
165	      flushTimer = null;
166	      flushBuffer().catch(() => {
167	        // Error already handled in flushBuffer
168	      });
169	    }, flushIntervalMs);
170	  }
171	
172	  /**
173	   * Add events to browser flush hooks
174	   */
175	  if (typeof window !== "undefined") {
176	    window.addEventListener("visibilitychange", () => {
177	      if (document.visibilityState === "hidden") {
178	        flushBuffer().catch(() => {});
179	      }
180	    });
181	
182	    window.addEventListener("beforeunload", () => {
183	      // Synchronous flush attempt (may not complete)
184	      if (buffer.length > 0) {
185	        // Use sendBeacon if available
186	        if (navigator.sendBeacon) {
187	          const blob = new Blob([JSON.stringify({ events: buffer })], {
188	            type: "application/json",
189	          });
190	          navigator.sendBeacon(url, blob);
191	        }
192	      }
193	    });
194	  }
195	
196	  const sink: Sink = (batch: LogEvent[]) => {
197	    // Add to buffer
198	    buffer.push(...batch);
199	
200	    // Drop oldest if over limit
201	    if (buffer.length > maxQueue) {
202	      const excess = buffer.length - maxQueue;
203	      buffer.splice(0, excess);
204	    }
205	
206	    // Flush if batch size reached
207	    if (buffer.length >= batchSize) {
208	      flushBuffer().catch(() => {});
209	    } else {
210	      scheduleFlush();
211	    }
212	  };
213	
214	  sink.flush = async (): Promise<void> => {
215	    if (flushTimer) {
216	      clearTimeout(flushTimer);
217	      flushTimer = null;
218	    }
219	    await flushBuffer();
220	  };
221	
222	  return sink;
223	}
  1	/**
  2	 * WatchFn ingest handler
  3	 */
  4	
  5	export interface WatchLogsHandlerOptions {
  6	  /** Authentication configuration */
  7	  auth?:
  8	    | {
  9	        header: string;
 10	        value: string;
 11	      }
 12	    | {
 13	        verifyToken: (req: Request) => boolean;
 14	      };
 15	
 16	  /** Maximum batch size (default: 500) */
 17	  maxBatch?: number;
 18	}
 19	
 20	/**
 21	 * Create a WatchFn logs ingest handler
 22	 * Route: POST /watch/logs
 23	 * Body: { events: LogEvent[] }
 24	 */
 25	export function watchLogsHandler(options: WatchLogsHandlerOptions = {}) {
 26	  const { maxBatch = 500, auth } = options;
 27	
 28	  return async (req: Request): Promise<Response> => {
 29	    // Verify authentication
 30	    if (auth) {
 31	      let authorized = false;
 32	
 33	      if ("verifyToken" in auth) {
 34	        authorized = auth.verifyToken(req);
 35	      } else {
 36	        const headerValue = req.headers.get(auth.header);
 37	        authorized = headerValue === auth.value;
 38	      }
 39	
 40	      if (!authorized) {
 41	        return new Response(JSON.stringify({ error: "Unauthorized" }), {
 42	          status: 401,
 43	          headers: { "Content-Type": "application/json" },
 44	        });
 45	      }
 46	    }
 47	
 48	    // Parse body
 49	    let body: unknown;
 50	    try {
 51	      body = await req.json();
 52	    } catch {
 53	      return new Response(JSON.stringify({ error: "Invalid JSON" }), {
 54	        status: 400,
 55	        headers: { "Content-Type": "application/json" },
 56	      });
 57	    }
 58	
 59	    // Validate schema
 60	    if (!body || typeof body !== "object" || !("events" in body)) {
 61	      return new Response(JSON.stringify({ error: "Missing events field" }), {
 62	        status: 400,
 63	        headers: { "Content-Type": "application/json" },
 64	      });
 65	    }
 66	
 67	    const { events } = body as { events: unknown };
 68	
 69	    if (!Array.isArray(events)) {
 70	      return new Response(
 71	        JSON.stringify({ error: "Events must be an array" }),
 72	        {
