  9	 */
 10	export function registerProcessHandlers(logger: Logger): () => void {
 11	  if (typeof process === "undefined") {
 12	    throw new Error(
 13	      "registerProcessHandlers can only be used in Node.js environments"
 14	    );
 15	  }
 16	
 17	  let shuttingDown = false;
 18	
 19	  const shutdownHandler = (signal: string) => async () => {
 20	    if (shuttingDown) {
 21	      return;
 22	    }
 23	
 24	    shuttingDown = true;
 25	    logger.info(`Received ${signal}, flushing logs...`);
 26	
 27	    try {
 28	      await logger.flush();
 29	      logger.info("Logs flushed successfully");
 30	    } catch (error) {
 31	      console.error("[logfn] Failed to flush on shutdown", error);
 32	    } finally {
 33	      process.exit(0);
 34	    }
 35	  };
 36	
 37	  const sigtermHandler = shutdownHandler("SIGTERM");
 38	  const sigintHandler = shutdownHandler("SIGINT");
 39	
 40	  process.on("SIGTERM", sigtermHandler);
 41	  process.on("SIGINT", sigintHandler);
 42	
 43	  // Return cleanup function
 44	  return () => {
 45	    process.off("SIGTERM", sigtermHandler);
 46	    process.off("SIGINT", sigintHandler);
 47	  };
